import React, { useEffect, useState } from 'react';
import {useParams, useNavigate } from 'react-router-dom';
import TeacherHeader from './TeacherHeader';
import '../css/TeacerAddChapter.css';
import './css/assignment.css';
import PosterImg from '../images/Iboadage.jpg';
import PostImg from '../images/cos.png';
import axios from 'axios'
const BASEURL = 'http://127.0.0.1:8000'
const teacherId = localStorage.getItem('teacherId')
const AssignmentUpload = () => {
    const [fetcherror, setFetchError] = useState(false)
    const [succeeded, setSucceeded] = useState(false)
    const [videoError ,setVideoError] = useState(false)
    const [disabled, setDisabled] = useState(false)
    const [processing, setProcessing] = useState(false)
    const [courses, setCourses] = useState([])
    
    const [assignment, setAssignment] = useState({
        course: '',
        title: '',
        detail: '',
        documents: '',
        teacher: '',
    }) 

    // Fetching the previous data
    useEffect(() => {
       try{
        axios.get(BASEURL + '/courses/')
        .then((res) => {
            setCourses(res.data)
            console.log('response is of course => ', res.data)
        })
       }catch(error){
            console.log(error)
        }

    },[])


    // useEffect(() => {
    //     try{
    //      axios.get(BASEURL + '/student-assignment/1/1/')
    //      .then((res) => {
    //          setAssignment({
    //              title: res.data.title,
    //              file: res.data.file,
    //              detail: res.data.detail,
    //          })
    //          console.log('response is => ', res.data)
    //      })
    //     }catch(error){
    //          console.log(error)
    //      }
 
    //  }, [])

    const {course_id} = useParams()
    const navigate = useNavigate()

    const handleChange = (event) => {
        setAssignment({
            ...assignment,
            [event.target.name]: event.target.value
        })
    }
    const handleFileChange = (event) => {
        setAssignment({
          ...assignment,
          [event.target.name]: event.target.files[0]
        })
      }
    
    const handleSubmit = (e) => {
        e.preventDefault();
        setProcessing(true)
        setDisabled(true)
        const formData = new FormData();
        formData.append('teacher', teacherId)
        formData.append('title', assignment.title);
        formData.append('documents', assignment.documents);  
        formData.append('detail', assignment.detail);
        formData.append('course', assignment.course)

        axios.post(BASEURL + '/student-assignment/'+ assignment.course + '/' + teacherId + '/', formData, {
            headers : {
                'content-type' : 'multipart/form-data'
            }
        })
        .then(res => {
            setSucceeded(true)
            setProcessing(false)
            navigate('/add-assignment')
            console.log(res.data)
            //localhost:3000/course-list/3/chapter
        })
        .catch(error => {
            console.log(error)
            setSucceeded(false)
            setProcessing(false)
            setDisabled(false)
            setFetchError(true)
        })
    }  
console.log("Teacher  ", assignment.documents)
    return(
        <div className='assignment'>
            <TeacherHeader />
            <div className='upload_assignment'>
                <form>
                    <p className='fetch__error'><strong>{fetcherror && 'Something went wrong!' }</strong></p>
                    <label>Title</label>
                    <input onChange={handleChange} value={assignment.title} type='text' name="title" />
                    <label className='label2'> Select Course</label>
                    <select name='course' value={assignment.course} onChange={handleChange} className="select">
                        {
                            courses.map((course, index) => {
                                return(
                                    <option defaultValue={course.id[0]} value={course.id} key={index}>{course.topic}</option>
                                )
                            })
                        }
                    <option  className='option2'>Python</option>
                    <option  className='option2'>Java</option> 
                    </select>
                    <label>File if any</label>
                    <input onChange={handleFileChange} type='file' accept=".docs, .pdf, .txt"  name="documents" placeholder=''/>
                    <label>Assignment Body</label>
                    <textarea onChange={handleChange} value={assignment.detail} name='detail'></textarea>
                      <button disabled={processing || disabled || succeeded} onClick={handleSubmit} className='butns'>
                       <span> {processing ? 'Sending... wait!' : "Send" }</span> 
                    </button>
                    
                </form>
              </div>
        </div>
   
    )
}

export default AssignmentUpload;