import React, {useState, useEffect} from 'react';
import { Link, useParams } from 'react-router-dom';
import axios from 'axios';
import '../css/TeacherDetail.css';
import image from '.././static/images/Course2.jpg'
import { set } from 'date-fns';

const TeacherDetail = () => {
    const [teacherData, setTeacherData] = useState([]);
    const [course, setCourse] = useState([]);    
    const [teacher, setTeacher] = useState([]);
    const [teacherCourse, setTeacherCourse] = useState([]);
    const [courses, setCourses] = useState([]);

    const {course_id} = useParams();

    useEffect(() => {
            axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student/courses/${course_id}/`)
            .then(res => {
                setCourse(res.data)
                setTeacherCourse(res.data.course_chapters)
                setTeacherData(res.data.category)
                setTeacher(res.data.teacher)
                console.log('teachers courses => ', res.data)
            })
            .catch(error => {
                console.log(error)
            })

    }, [])

    return(
        <div className='base__container'>
            <div  className='contain1'>
                <div className='img__tag'>
                 <img src={image} index='' className='videos' controls>
                </img>
                <span className='teacher__name'>{teacher.full_name} </span>
                </div>
            
                <div className='teacher__details'>
                    <div className='names'>
                        <h1>{teacherData.title}</h1>
                    <h2>Teacher Skills</h2></div>
                    <div className='others'>
                        <span><h3>Contact</h3></span>
                        <ul>
                            <li>Phone: <span>08338383383 </span></li>
                            <li>Email: <span> {teacher.email}</span></li>
                            <li>Rating: <span>Some rating</span></li>
                            <li>Qualifications: <span>{teacher.qualification}</span></li>
                        </ul>
                        
                        <article>
                            <h2>Biography</h2>
                            <p>Some Biography</p>
                        </article>

                    </div>
                </div>

                <div className='lines1'>    
                <div style={{background: 'black', color: 'black'}} className='lines'>IMTech</div>
                </div>

                <div className='courses2'>
                    <div>
                        <span><h2>Published Courses</h2></span>
                    </div>
                        <div className='cards'>
                                
                                {
                                    teacherCourse.map(cos => {
                                        return(
                                           <div className='course__card'>
                                            <img src={course.course_image} alt="" />
                                            <h3>{cos.title}</h3>
                                            </div>
                                        )
                                    })
                                }
                            
                            
                    </div>
                 </div>
            </div>
    </div>
        
    )
}

export default TeacherDetail