import React, {useState, useEffect } from 'react';
import axios from 'axios';
import Cookies from 'js-cookie';
import { connect } from 'react-redux';
import {useParams } from 'react-router-dom';
import CSRFToken from '../Components/CSRFToken.js';
import CourseImg from '../static/images/Course2.jpg';
import Image from '../static/images/nature-3082832_960_720.jpg';
import '../css/CourseDetail.css';
import YouTubeIcon from '@mui/icons-material/YouTube';
import VideoPlayer2 from './VideoPlayer2'
import image from './StudentData/css/anonymous.jfif';
import { Link, useNavigate } from 'react-router-dom';
import Swal from 'sweetalert2';
import { check_authenticated } from '../Redux/Actions/auth';

const CourseDetail = ({IsAuthenticated_student, studentId, check_authenticated}) => {
    //const IsAuthenticated_student = localStorage.getItem('studentLoginStatus')
    const navigate = useNavigate();
    const [courseData, setCourseData] = useState([]);
    const [video, setVideo]  = useState('')
    const [teacherData, setTeacherData] = useState([])
    const [chapterData, setChaperData] = useState([])
    const [category, setCategory] = useState([]);
    const [relatedCourse, setRelatedCourse] = useState([]);
    const [totalCourseEnrolled, setTotalCourseEnrolled] = useState([])
    const [enrolledStatus, setEnrolledStatus] = useState('');
    const [enrollCount, setEnrollCount] = useState([]);
    const [processing, setProcessing] = useState(false);
    const [disabled, setDisabled] = useState(false)
    const [favorite, setFavorite] = useState([])
    const [chpt, setChpt] = useState([])
    const [ratingStatus, setRatingStatus] = useState([])

    const [noChapter, setNoChapter] = useState(false)
    let {course_id} = useParams();

    
    useEffect(() => {
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student/courses/${course_id}/`)
        .then(res => {
            setCourseData(res.data);
            setTeacherData(res.data.teacher)
            setChaperData(res.data.course_chapters)
            setCategory(res.data.category)
            setRelatedCourse(JSON.parse(res.data.related_course))
            console.log('course-detail => ', chapterData)
        })
        .catch(error => {
            setNoChapter(true)
        })

        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-favorite-course/${studentId}/${course_id}/`)
        .then(res => {
            setFavorite(res.data)
        })
        .catch(err => {
            setFavorite("")
        })
    },[])

console.log("details", studentId)

// Enroll courses


useEffect(()=>{
axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-enroll-course/${course_id}/${studentId}/`)
.then(resp => {
    console.log("enrorrled students ", resp.data)
    setEnrolledStatus(resp.data)
    setEnrollCount(resp.data.studentEnrol)
    setProcessing(false)
})
.catch(error => {
    console.log("errors are ", error)
    setProcessing(false)
})

axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-enroll-course/${course_id}/${studentId}/`)
.then(res => {
    console.log("enrorrled courses here ", res.data)
    setTotalCourseEnrolled(res.data)

})

.catch(error => {
    console.log("errors are ", error)
    setProcessing(false)
})
},[course_id, studentId])

useEffect(() => {
    const config = {
        headers : {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'),
        }
    }

    try{
        axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/lms/rating-status/`, {studentId: studentId, course_id: course_id}, config)
        .then(res => {
            // setRatingStatus(res.data)
            setRatingStatus(res.data)
        })
        .catch(error => {
            console.log(error)
        })
    }
    catch(error){
        console.log(error)
    }
    
},[studentId, course_id])

const handleCourseEnroll = () => {
    setProcessing(true)
    setDisabled(true)
    const formData = new FormData();
    formData.append('course', course_id)
    formData.append('student', studentId)

    const config = {
        headers : {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'),
        }
    }

    {
        enrolledStatus.enrollCount >= 2 ?
        Swal.fire({
            title: 'Maximum limit of enrollment reached!',
            icon:'warning',
            toast: true,
            position: 'top',
            timer: 4000,
            timerProgressBar: true,
            showConfirmButton: false,
        })
        :
        axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-enroll-course/`, formData, config)
        .then(res => {
        if(res.status === 200 || res.status === 201){
            
            Swal.fire({
                title: 'You are now enrolled!',
                icon: 'success',
                toast: true,
                position: 'top',
                timer: 4000,
                timerProgressBar: true,
                showConfirmButton: false,
            })
        }

        setProcessing(false)
        setDisabled(false)
        // amcoming
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-enroll-course/${course_id}/${studentId}/`)
        .then(resp => {
            setEnrolledStatus(resp.data)
            setEnrollCount(resp.data.studentEnrol)
            setProcessing(false)
        })
        .catch(error => {
            setProcessing(false)
        })
    })
    .catch(error => {
        console.log(error)
        setProcessing(false)
    })
    }
}

console.log("Rating status here ", ratingStatus)

    return(
        <div className="course__detail">
            <CSRFToken />
            <div className='headings2'>
                <h2>Course Class</h2>
            </div>
            {/* Passing props to a component */}
           {
            IsAuthenticated_student ?
            <VideoPlayer2 chaptVideo = {video}
            favorite = {favorite}
            chapters={chapterData}
            topic={courseData.topic} teacher={teacherData.full_name} teacherId={teacherData.id}
            chapterId={chapterData.id}
            category={category.title} enrolled={enrolledStatus}
            loginStatus = {IsAuthenticated_student}
            ratingStatus={ratingStatus}
             />
             :
             <div className='text-lg text-danger h3 justify-content-center'>
             <span>You don't have access to this content</span> <br />
             <h6 className='text-dark'>Login and Enroll</h6>
             </div>
           } 
                {/* Course Videos */}
                <p>{video}</p>
        <div className='container mt-5 p-3'>
            <div className='row justify-content-center'>                
                <div className='card mb-2'>
                    <div className='card-header'>
                        Featured
                    </div>
                    {
                        IsAuthenticated_student ? (
                            enrolledStatus.enrolled ? 
                            (
                        <ul class="list-group list-group-flush">
                       {
                        chapterData.map(chapter => {
                            return(
                        <li className='list-group-item text-success'> 
                    <Link to={`/detail/play/${chapter.id}`} >{chapter.title}</Link>  
                        <i className='point float-end'><YouTubeIcon /></i></li>
                            )
                        })
                       }
                       
                        </ul>
                        ) 
                        :
                        (
                        <ul className="list-group list-group-flush">
                        <li className='list-group-item text-info'> 
                            You are not enrolled in this course  
                        <i className='point float-end'><YouTubeIcon /></i></li>
                        </ul>
                        )
                        )
                        :
                        (
                        <ul className="list-group list-group-flush">
                         <li className='list-group-item text-danger'> 
                            Please Login to Enroll
                         <i className='point float-end'><YouTubeIcon /></i></li>
                        </ul>
                        )
                        
                    }
                </div>
            </div>
            <div className='row'>
                <div className='col'>
                    {/* <Link to="/detail/:course_id/video"> */}
                    {
                       IsAuthenticated_student ?
                            (
                               enrolledStatus.enrolled ? 
                                (<button className='btn btn-success'>Your are enrolled</button>) 
                                :    
                                (
                                <>
                                <button disabled={processing || disabled}  onClick={handleCourseEnroll} className='btn btn-success text-white'>
                                    {processing ? "wait while loading..." : 'Enroll this course'}
                                </button>
                                <p className="text-danger">
                                   Note:{'  '} You can only enroll in a maximum of two{' (2)'} courses, please be mindful of the courses you enroll!
                                </p>
                                <small style={{color: 'grey'}} className='mt-0'>Learning never ends! you may listen but not your enrolled course</small>
                                </>
                                
                                    
                                )
                            
                                )
                            :
                            (
                            <Link to="/auth/login">
                            <button className='btn btn-danger'>Anonymous</button>
                            </Link> 
                            )
                    }
                    {/* </Link> */}
                </div>
            </div>

            <div className='row mt-5'>
                <h4>Related Courses</h4>
                {
                    IsAuthenticated_student ? 
                    <>
                    {
                    relatedCourse.map(related => {
                        return(
                    <div className='col-4 col-md-3 mt-2 mb-3'>
                        <div className='card' style={{ width: '100%'}}>
                        <img className="card-i" src={`${`${process.env.REACT_APP_LMS_BASE_URL}/lms/`}/media/${related.fields.course_image}/`} alt='' />
                        <div className='card-b'>
                           <Link target='__blank' to={`/detail/play/${related.pk}`}>
                            <h4 className='card-title font-2 h6 text-muted'>{related.fields.topic}</h4>
                            </Link> 
                         </div>
                    </div>
                </div>   
                        )
                    })
                }
                    </>
                    :
                    <div className='col-4 col-md-3 mt-2 mb-3'>
                    <div className='card' style={{ width: '100%'}}>
                    <img className="card-i" src={image} alt='please login' />
                    <div className='card-b'>
                       <Link target='_blank' to="{`/detail/play/${related.pk}`}">
                        <h4 className='card-title font-2 h6 text-muted text-danger'>Anonymous</h4>
                        </Link> 
                     </div>
                    </div>
            </div> 
                }
                
            </div>        
        </div>
        
        </div>
    )
}

const mapStateToProps = state => ({
    IsAuthenticated_student:state.auth.IsAuthenticated_student,
    studentId: state.profile.studentId
})
export default connect(mapStateToProps, {check_authenticated})(CourseDetail);