import React, {useState, useEffect} from 'react' 
import axios from 'axios';
import '../css/TeacherCourse.css';
import { useParams } from 'react-router-dom';
import {format} from 'date-fns';
import EditIcon from '@mui/icons-material/Edit';
import {Link} from 'react-router-dom';


const BASE_URL = 'http://127.0.0.1:8000/lms'



const CourseChapter = () => {
    // Constants
    const [chapter, setChapter] = useState([]);
    const [chapterLen, setChapterLen] = useState(0);
    const {course_id} = useParams()
    const [courseRating, setCourseRatings] = useState(0);
    const [avgRating, setAvgRatings] = useState({})

    useEffect(() => {
        axios.get(BASE_URL + `/chapter/` + course_id + "/")
        .then((res) => {
            setChapter(res.data)
            setAvgRatings(JSON.parse(res.data.average_rating))
            setChapterLen(res.data.length)
            console.log("watch out ", res.data)
        })
        .catch(error => {
            console.log(error.data)
        })

        console.log("testing ", chapterLen)

        axios.get(`${BASE_URL}/course-rating/${course_id}/`)
        .then(res => {
            setCourseRatings(res.data)
            // console.log('one of course rating ', res.data)
        })
        .catch(error => {
            console.log("error ", error)
        })
    },[])

    return(
        <div className='course__chapter'>
            <div className='main1'>
               <div className='course__chapter__header'>
                    <h2>You have {'('}<code style={{fontWeight: '800', fontStyle: 'italic'}}>{chapterLen}</code> {')'} {
                        chapterLen >= 2 ? 'chapters' : 'chapter'
                    } associated with this topic</h2>
                    {/* <p className='fetch__error'>
                      { chapterError ?
                         chapterError.map(error => {
                            return(
                                <p>
                                    <span>{error}</span>
                                </p>
                            )
                        }) : ''
                      } 
                    </p> */}
                </div>
            <div className='tables1'>
                <table>
                    <thead className='thead1'>
                        <tr>
                            <th>
                             Sub Topics
                            </th>
                            <th>
                                Rates
                            </th>

                            <th>
                                Preview/Video
                            </th>

                            <th>
                                Date/Time
                            </th>
                            
                            <th>
                                Action
                            </th>
                        </tr>
                    </thead>
                    {
                        chapter.map(chapt => {
                            return(
                         <tbody className='tbody1'>
                                <tr> 
                                    <td className='title1'>{chapt.title}</td>  
                                        <td className='rating1'>
                                            <Link to={`/reviews/chapter/${course_id}`}>{chapt.average_rating.rating__avg/5 * 100}%</Link>
                                        </td>
                                    <td>
                                        <video className='videos' width="75px" controls>
                                            <source src={chapt.video}  type='video/mp4'/>
                                        </video>
                                    </td>  
                                    <td>
                                        {
                                            format(new Date(chapt.created), 'dd/MM/yyyy')
                                        }
                                    </td>
                                    <td>
                                        <div className='butn'>
                                        <button className='but4 btn2 text-danger'>Delete</button>
                                       <Link to={'/course-list/chapter/'+ chapt.id + '/edit'}> <button className='but btn2'>Edit</button></Link> 
                                        </div>
                                    </td>
                                </tr>
                            </tbody>
                            )
                        })
                    }
                    
                </table>
            </div>  
            </div>
           
        </div>
    )
}

export default CourseChapter;