import React, { useState, useEffect} from 'react';
import TeacherHeader from './TeacherHeader';
import '../css/AddCourse.css';
import axios from 'axios';
import { connect } from 'react-redux';
import { green } from '@mui/material/colors';
import { useNavigate, useParams } from 'react-router-dom';
import Cookies from 'js-cookie';
import CSRFToken from '../../../Components/CSRFToken';



const TeacherCourseEdit = ({teacherId}) => {
const navigate = useNavigate()

// *****************   Functionality of the page   ***************//
const [processing, setProcessing] = useState(false)
const [disabled, setDisabled] = useState(false)
const [success, setSuccess] = useState(false)
const [noImg, setNoImg] = useState(false)
const [courseDataError, setCourseDataError] = useState(false)
const [category, setCategory] = useState([])
const [teacher, setTeacher] = useState([])
const {course_id} = useParams();

const [courseData, setCourseData] = useState({
    id: '',
    topic: '',
    course_image: null,
    description: '',
    course_duration: '',
    teacher: '',
    category: '',
})


useEffect(()=>{
    axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/course-category/`)
    .then((response) => {
        setCategory(response.data)
    })
    .catch(error => {
        console.log("error ", error.data)
    })
},[])

useEffect(() => {
    //Teacher APi
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/teachers/`)
        .then(res => {
            setTeacher(res.data)
        })
        .catch((error) => {
            console.log(error)
        })
    // Course Details apis
    axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/courses/${course_id}/`)
    .then((res) => {
        setCourseData({
            category: res.data.category,
            topic: res.data.topic,
            description: res.data.description,
            prev_image: res.data.course_image,
            course_image: '',
            course_duration: res.data.course_duration,
            time: res.data.time,
        })
        console.log(res.data)
    })
    .catch(error => {
        console.log(error.data)
    })
}, [])

// console.log(teacher, ' hear')

const handleChange = (event) => {
    setCourseData({
        ...courseData,
        [event.target.name]: event.target.value
    })

}

const handleFileChange = (event) => {
        setCourseData({
            ...courseData,
            [event.target.name]: event.target.files[0]
        })
}

const handleSubmit = e => {
    e.preventDefault()
    setDisabled(true)
    setProcessing(true)
    const form_Data = new FormData();
    form_Data.append('category', courseData.category);
    form_Data.append('topic', courseData.topic);
    form_Data.append('description', courseData.description);
    form_Data.append('course_duration', courseData.course_duration);
    if(courseData.course_image !== ''){
        form_Data.append('course_image', courseData.course_image);
    }
    else{
        setNoImg(true)
    }
    form_Data.append('teacher', teacherId);

    axios.put(`${process.env.REACT_APP_LMS_BASE_URL}/lms/courses/${course_id}/`, form_Data, {
        headers:{
            'content-type': 'multipart/form-data',
            'X-CSRFToken': Cookies.get('csrftoken')
        }
    })
    .then( resp => {
        setCourseData(resp.data)
        setSuccess(true)
        setProcessing(false)

        if(processing || success == false){
        navigate('/course-list')
        }

        //window.location.href='/course-list'
    })
    .catch(error => {
        console.log(error)
        setCourseDataError(true)
        setProcessing(false)
        setSuccess(false)
        setDisabled(false)
    })}

   

// ********** END Functionality of the page  ************//


    return(
        <div className='course__add'>
            <div className='header'>
                <h3>Edit Course</h3>
            </div>
            <div className='forms'>
                <form>
                    <CSRFToken />
                    <label className='label2'>Course Topic</label>
                    <input name='topic' onChange={handleChange} value={courseData.topic} className='input2 text2' type='text' placeholder='' />

                    
                    <label className='tex1'>Course Durations</label>
                    <input name='course_duration' value={courseData.course_duration} onChange={handleChange} className='input2 text1' type='text' placeholder='eg. 1hour 2hrs' />
                
                    <label className='label2'>Description</label>
                    <textarea name='description'value={courseData.description} onChange={handleChange} className='textarea'></textarea>

                    <label className='label2' > Select Course</label>
                    <select name='category'value={courseData.category} onChange={handleChange} className="select">
                    {
                    category.map(
                        (categ, index) => {return <option value={categ.id} className='option2' key={index}>{categ.title}</option> }  
                          )
                    }
                    </select>

                    {/** This is teacher selection input */}
                    {/* <label className='label2'>Course Owner</label>
                    <select name='teacher' onChange={handleChange} className='select'>
                        {
                            teacher.map(
                                (name, index) => {
                                return <option value={teacher.id} className='option2' key={index}>{name.idcd}</option>
                            })
                        }
                    </select> */}

                    <label className='label2'>Thumbnail Image</label>
                    <input name='course_image' className="input2" onChange={handleFileChange} type='file' accept="image/gif, image/jpeg"  id='' />  
                    <img className='thumbnail' src={ courseData.prev_image } width="200px"   />
                    
                    <button disabled={processing || disabled || success} onClick={handleSubmit} className="butt">
                        <sapn>{processing ? "Wait... uploading" : "Upload"}</sapn> 
                    </button>    
                    
                </form>
            </div>
        </div>
    )
}
const mapStateToProps = state => ({
    teacherId: state.profile.teacherId,
})
export default connect(mapStateToProps, {})(TeacherCourseEdit);