import React from 'react'
import './Loading.css';
import icon from './IMtech.png'

function Loading() {
  return (
    <div className='loading__page'>
      <div className='position'>
        <div className='laoding__img'>
            <img src={icon} alt='' />
        </div>
        <div className='ch5'><h5>Change your world!</h5></div>
        <div className='loading__battery'>
            <div className='battery__level'></div>
            <div className='battery__flash'></div>
        </div>
      </div>
      
    </div>
  )
}

export default Loading