import React, { useEffect } from 'react';
import {connect} from 'react-redux';
import Container from 'react-bootstrap/Container';
import { logout } from '../Redux/Actions/auth';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import NavDropdown from 'react-bootstrap/NavDropdown';
import '../css/Navbar1.css';
import {Link, useNavigate} from 'react-router-dom';
import CssTutorial from '../css/CSS_Tutorial/CssTutorial';
import { check_authenticated } from '../Redux/Actions/auth';
import { student_profile } from '../Redux/Actions/profile';

const Navbar1 = ({IsAuthenticated_student, logout, check_authenticated, student_profile }) => {
 const navigate = useNavigate();
  
 useEffect(() => {
  student_profile()
  
  // try{
  //     if(IsAuthenticated_student){
  //       student_profile()
  //         navigate('.')
  //      } else{ 
  //         navigate('/teacher-login')
  //      }
  // }
  // catch(error){
  //     console.log(error)
  // }

},[IsAuthenticated_student])

const handleLogout = () => {
  const verify = window.confirm("Are you sure?")
  if(verify){
    logout()
    navigate('/')
  }
}

  return (
    <Navbar className="navbar1" bg="dark" variant="dark" expand="lg">
      <Container className="">
        {
          IsAuthenticated_student ?

           <Navbar.Brand ><Link style={{textDecoration:"none", color:"blue"}} to="/dashboard">IMTech</Link></Navbar.Brand>

          :
          <Navbar.Brand ><Link style={{textDecoration:"none", color:"blue"}} to="/">IMTech</Link></Navbar.Brand>
        }

        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            <Nav.Link href="/dashboard">Home</Nav.Link>
            <Nav.Link href="#link"><Link style={{textDecoration:"none"}} to="/about">About</Link></Nav.Link>
              {
                IsAuthenticated_student ?
              (
              <NavDropdown bg="black" title="Profile" variant="" id="basic-nav-dropdown">
                <NavDropdown.Item href="#action/3.1">Courses</NavDropdown.Item>
                <NavDropdown.Item href="#action/3.2">
                  Teacher
                </NavDropdown.Item>
                <Link style={{textDecoration: "none"}} to="/css-tutorial"><NavDropdown.Item href="#action/3.3">
                  Css Practice</NavDropdown.Item></Link>
                <NavDropdown.Divider />
                <NavDropdown.Item href="#action/3.4">
                  Your Attendances
                </NavDropdown.Item>
                {/* Tenary Operator here */}
            
                <NavDropdown.Item>
                  <span style={{textDecoration: "none"}} onClick={handleLogout}>Logout</span>
                </NavDropdown.Item>
                {/* end Tenary Operator here */}
              </NavDropdown>
              )
              
              :
              
              (
                <NavDropdown bg='black' title="Class" variant="" id="basic-nav-dropdowon">
                  <NavDropdown.Item>
                    <Link style={{textDecoration: "none"}} to="/">Login</Link>
                  </NavDropdown.Item>
                </NavDropdown>
              )
            }

          </Nav>   
        </Navbar.Collapse>
      </Container> 
    </Navbar>
  );
}


const mapStateToProps = state => ({
  IsAuthenticated_student: state.auth.IsAuthenticated_student
})
export default connect(mapStateToProps,  {student_profile, logout, check_authenticated})(Navbar1);