import React, { useEffect, useState } from 'react'
import './css/StudentEnrolled.css';
import { useParams } from 'react-router-dom';
import axios from 'axios';

function StudentEnrolled() {
    // Constants
    const {course_id} = useParams();
    const [enrolled, setEnrolled ] = useState([])
    const maxLength = 7;

    // Functions
    useEffect(() => {
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/fetched-enrolled-student/${course_id}/`)
        .then(res => {
            setEnrolled(res.data)
            console.log(res.data)
        })
        .catch(error => {
            console.log("Error output => ", error.data)
        })
    },[])

    const handleSubString = (text, maxLength) => {
        if(text.length <= maxLength){
            return text
        }
        return text.substring(0, maxLength) + '...'
    }
  return (
    <div className='student__enrolled'>
        <div className='st_enrolledHeader'>
            <h2>Enrolled Students</h2>
        </div>

        <div className='st__enrolledList'>
            <table>
                <thead>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Course</th>
                </thead>
                {
                    enrolled.map(students => {
                        return(
                <tbody>
                    <td>{students?.student.username}</td>
                    <td>{students.student.email == "" ? (<i>Pending profile</i>) : (<i>{students.student.email}</i>)} </td>
                    <td>{handleSubString(students.course.topic, maxLength)}</td>
                </tbody>  
                        )
                    })
                }
            </table>
        </div>
    </div>
  )
}

export default StudentEnrolled