import React, { useEffect, useState } from 'react';
import NotificationsIcon from '@mui/icons-material/Notifications';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import { Link, useNavigate } from 'react-router-dom';
import '../TeacherDashboard/css/TeacherHeader.css';
import { connect } from 'react-redux';
import profile from '../../../Redux/Reducers/profile';
import { load_techer_user } from '../../../Redux/Actions/profile';
import { check_authenticated } from '../../../Redux/Actions/auth';
import { logout } from '../../../Redux/Actions/auth';

const teacherCourse = localStorage.getItem('teacherCourse')

const TeacherHeader = ({profile, teacherId, is_teacher, course, email, username, loading, logout, IsAuthenticated}) => {
    const [isOpen, setIsOpen] = useState(false)

    const handleUserMouseEnter = () => {
        setIsOpen(true) 
    }
    const handleUserMouseLeave = () => {
        setIsOpen(false)
    }

    useEffect(() => {
        // Add event listener for mouse enter and mouse leave
        const dropdownElement = document.getElementById('dropdown')

        dropdownElement.addEventListener('mouseenter', handleUserMouseEnter);
        dropdownElement.addEventListener('mouseleave', handleUserMouseLeave);

        // Then cleanup the event listener
        return () => {
            dropdownElement.removeEventListener('mouseenter', handleUserMouseEnter)
            dropdownElement.removeEventListener('mouseleave', handleUserMouseLeave);
        }

    },[])

    useEffect(() => {
        try{
            if(IsAuthenticated){
                navigate('.')
             } else{ 
                navigate('/')
             }
        }
        catch(error){
            console.log(error)
        }
    },[IsAuthenticated])

    const handleLogout = () => {
        const verify = window.confirm("Are you sure?")
        if(verify){
          logout()
          navigate('/')
        }
    }
    const navigate = useNavigate();
    console.log("The values are shaa ", username, email, course, teacherId)
    return(
        <div className='teacher__header'>
            <div className='header__icon'>
                {
                    IsAuthenticated ?
                     <div className='text'><span><i style={{fontSize: '.8rem', color:'yellow'}}>Welcome @</i>{email}</span><code>{course}</code></div>
                     :
                     <div className='text'><span><i style={{fontSize: '.8rem', color:'yellow'}}>Welcome @</i>Guest</span></div>

                }
                {
                    is_teacher ?
                    (
                    <div className='imagery'>
                    <div className='icon notify'><NotificationsIcon /></div>
                  <Link to="/course-list"><div className='icon time'><AccessTimeIcon /></div></Link>  
                   <Link to="/add-course"><div className='icon cloud'><CloudUploadIcon /></div></Link> 
                    <div id="dropdown" className='icon'><span ><AccountCircleIcon onClick={() => setIsOpen(!isOpen)} /></span></div>
                    {isOpen && 
                        <ul onMouseOver={handleUserMouseEnter} onMouseLeave={handleUserMouseLeave} className='dropdown__content'>
                           
                            <Link to="/teacher/profile"><li>Setting</li></Link>
                            {
                                IsAuthenticated ? 
                                <>
                                
                                <li>{username}</li>
                                <li> <Link to="/add-assignment" >Assignment</Link></li>
                                <li><Link to="/course-list" >Courses</Link></li>
                                <div className='divider'></div>
                                <span style={{textAlign:'center'}} onClick={handleLogout}>
                                    <li>{loading ? "wait..." : 'Logout' }</li>
                                </span>

                                </>
                                
                                :
                                <>
                                <div className='divider'></div>
                                <Link to='teacher-login'  style={{textAlign:'center'}}><li>Login</li></Link>
                                </>
                            }
                        </ul>
                        }
                    <div className='image'><img src='' alt="" /></div>
                    </div> 
                    )
                    :
                    (
                        <div className='imagery'>
                        <div className='icon notify'><NotificationsIcon /></div>
                      <Link to="."><div className='icon time'><AccessTimeIcon /></div></Link>  
                       <Link to="."><div className='icon cloud'><CloudUploadIcon /></div></Link> 
                        <div id="dropdown" className='icon'><span ><AccountCircleIcon onClick={() => setIsOpen(!isOpen)} /></span></div>
                       
                        <div className='image'><img src='' alt="" /></div>
                   </div>
                    )
                }      
               
            </div>
        </div>
    )
}

const mapStateToProps = state => ({
    username: state.profile.username,
    teacherId: state.profile.teacherId,
    course: state.profile.course,
    email: state.profile.email,
    loading: state.auth.loading,
    IsAuthenticated: state.auth.IsAuthenticated,
    is_teacher: state.profile.is_teacher,
})
export default connect(mapStateToProps, {logout, load_techer_user, check_authenticated})(TeacherHeader);
