import React, { useEffect } from 'react';
import { connect } from 'react-redux';
import './TeacherAuth/css/TeacherAuth.css';
import LandingPage from './LandingPage';
import { useNavigate } from 'react-router-dom';


const LanderPage = ({is_student, is_teacher}) => {
    const navigate = useNavigate()
    useEffect(() => {
        if(is_student){
            navigate('/dashboard')
        }
    },[is_student])


    useEffect(() => {
        if(is_teacher){
            navigate('/teacher-index')
        }
    },[is_teacher])

    return(
        <div className="teacher__auth">
            <LandingPage />
        </div>
    )
}

const mapStateToProps = state => ({
    is_student: state.profile.is_student,
    is_teacher: state.profile.is_teacher
})

export default connect(mapStateToProps, {})(LanderPage);