import React, { useEffect, useState } from 'react';
import {useParams, useNavigate } from 'react-router-dom';
import { connect } from 'react-redux';
import CSRFToken from '../../../Components/CSRFToken';
import Cookies from 'js-cookie';
import TeacherHeader from './TeacherHeader';
import '../css/TeacerAddChapter.css';
import PosterImg from '../images/Iboadage.jpg';
import PostImg from '../images/cos.png';
import axios from 'axios'


const TeacherAddChapter = () => {
  const [processing, setProcessing] = useState(false)
  const [succeeded, setSucceeded] = useState(false)
  const [disabled, setDisabled] = useState(false)
  const [errors, setErrors] = useState(false)

  const {course_id} = useParams()
  const [emptyTitle, setEmptyTitle] = useState(false)
  const [emptyVideo, setEmptyVideo] = useState(false)
  const [emptyRemark, setEmptyRemark] = useState(false)

  const [chapterData, setChapterData] = useState({
    'ref_course': '',
    'title': '',
    'video': '',
    'remark': '',
  })

  const handleChange = (e) => {
    setChapterData({
      ...chapterData,
      [e.target.name]: e.target.value
    })
  }

const handleFileChange = (e) => {
    setChapterData({
      ...chapterData,
      [e.target.name]: e.target.files[0]
    });
  }
  //Use navigate to refresh the page after sumbittinh
const navigate = useNavigate()

  const handleSubmit = (e) => {
    e.preventDefault();
    setProcessing(true)
    setDisabled(true)
   const formDatah = new FormData();
   formDatah.append('ref_course', course_id)
   
   if(chapterData.title !== ''){
    formDatah.append('title', chapterData.title);
   }else(
    setEmptyTitle(true)
   )
   if(chapterData.video !== ''){
    formDatah.append('video', chapterData.video);
   }else(
    setEmptyVideo(true)
   )
    formDatah.append('remark', chapterData.remark);

   axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/lms/chapter/`, formDatah, {
    headers:{
      'content-type':'multipart/form-data',
      'X-CSRFToken': Cookies.get('csrftoken')
    }
   })
   .then(resp => {
    console.log(resp)
      setSucceeded(true)
      setProcessing(false)
      navigate('/course-list') 
   })
   .catch(error => {
    console.log(error)
    setErrors(true)
    setProcessing(false)
    setDisabled(false)
   })

  }

    return(
        <div className='teacher_add_chapter'>           
        <div className='page_body'>
             <div className='chapter_head'>
                <h2 className='h2'>Add Chapters</h2>
            </div>
            <div className='section'>
              <div className='posters'>
                <img src={PostImg} alt="" />
                <img className="img1" src={PosterImg} alt="" />
              </div>
              <div className='form_section'>
              <h3 className='h3'><span className='info'>Warning! </span> Upload your video, specific to what you teach.</h3>
                <form className='formik'>
                    <label>chapter title </label>
                    <CSRFToken />
                    <input onChange={handleChange} type='text' name="title" />
                    <span className='empty'>{emptyTitle && 'title field must not be empty!'}</span>
                    <label>Video </label>
                    <input onChange={handleFileChange} type='file'  accept="video/mp4" name="video" />
                    <span className='empty'>{emptyVideo && 'video field must not be empty!'}</span>

                    <label>Remark</label>
                    <textarea onChange={handleChange} name='remark'></textarea>
                      <button disabled={processing || disabled || succeeded} onClick={handleSubmit} className='butns'>
                        <span>
                          {processing ? 'wait, uploading...' : 'Upload'}
                        </span>
                      </button>
                    
                </form>
              </div>
            </div>
            
        </div>
            
        </div>
    )
}

export default TeacherAddChapter;