import React, {useEffect, useState} from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../Auth/CSS/Signup.css';
import '../Auth/CSS/Auth.css';
import '../Auth/CSS/Login.css';


const Login = () => {
    const BASE_URL = 'http://127.0.0.1:8000';
    const [error, setError] = useState(false);
    const [loginError, setLoginError] = useState(null);
    const navigate = useNavigate();
    const [studentLogin, setstudentLogin] = useState({
        'email': '',
        'password': '',
    })
    
    console.log(studentLogin)

    const handleChange = (event) => {
        setstudentLogin({
            ...studentLogin,
            [event.target.name]:event.target.value,
        })
    }

    const handleSubmit = (event) => {
        event.preventDefault();
        const studentFormData = new FormData()
        studentFormData.append('email', studentLogin.email);
        studentFormData.append('password', studentLogin.password);

        axios.post(BASE_URL + '/lms/student/login/', studentFormData)
        .then(res => {
            if(res.data.login === true){
                localStorage.setItem('studentLoginStatus', true)
                localStorage.setItem('studentId', res.data.student_id)
                localStorage.setItem('studentCourse', res.data.student_course)
                localStorage.setItem('studentName', res.data.student_name)

                navigate('/dashboard')
            }
            else{
                setLoginError("Wrong email or password!")
            }
            
        })
        .catch(error => {
            setError(true)
            console.log(error)
        })
    }
    useEffect(()=>{
        document.title = 'Enroll student';

    const studentLoginStatus = localStorage.getItem('studentLoginStatus');
     if(studentLoginStatus === 'true'){
        document.title = 'redirecting...'
        window.location.href = '/dashboard'
    }

    },[])
    
   
    return(
        <div className='auth'>
            <div className="student__login">
                <h2>Todays students, forms the hope of the Nations</h2>
            </div>
        <div className='login__container'>
            
            <div className='form'>
            <label>Login</label>
            <div className='error'>
               <h4>{error && "Something went wrong"}</h4> 
               <h4>{loginError && loginError}</h4> 
            </div>
            <input onChange={handleChange} type="email" name='email' placeholder='email' />
            <input onChange={handleChange} type="password" name='password' placeholder="password" />
                <p>
                    <input className="checkBox" type="checkbox" name="remember" value="Remember me" />Remember me
                </p>
            <button onClick={handleSubmit} className='login__button'>login</button>
            </div>
            <div className='log'>
                <p> Don't have an account yet? <Link to="/auth">Sign Up here</Link></p>
            </div>
        </div> 
        </div>
        
    )
}

export default Login;