import React, { useEffect } from 'react';
import { connect } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import '../css/Index.css';
import Sidebar from '../SideBarSection/Sidebar';
import '../css/Sidebar.css';
import '../css/TeacherIndex.css';
import TeacherDash from '../TeacherDashboard/TeacherDash';
import SidebarTeacher from '../SideBarSection/SidebarTeacher';
import { check_authenticated } from '../../../Redux/Actions/auth';

const TeacherIndex = ({check_authenticated, IsAuthenticated}) => {
    const navigate = useNavigate()

        useEffect(() => {
            if(IsAuthenticated !== false){
               navigate('.')
            }else{ 
                navigate('/teacher-login')
            }
        },[IsAuthenticated])

    return(
        <div className='main__content2'>
            <TeacherDash />
        </div>
    )
}
const mapStateToProps = state => ({
    IsAuthenticated: state.auth.IsAuthenticated
})
export default connect(mapStateToProps, check_authenticated)(TeacherIndex);