import React, {Fragment, useEffect} from 'react'
import Navbar1 from '../../Components/Navbar1'
import { connect } from 'react-redux'
import { check_authenticated } from '../Actions/auth' 
import { load_techer_user } from '../Actions/profile'
import TeacherHeader from '../../Dashboard/Components/TeacherDashboard/TeacherHeader'
import { useNavigate } from 'react-router-dom'



const Layout = ({children, check_authenticated, isAuthenticated, email}) => {
  const navigate = useNavigate()
  
  useEffect(() => {
    // if(isAuthenticated){
    //   navigate('.')
    // }else{
    //   navigate('/')
    // }
    check_authenticated();
  },[])
  
  useEffect(() => {
    load_techer_user();
  },[email])

  return (
    <Fragment>
      {
        email ?
        (
        <TeacherHeader />
        )
        :
        (
        <Navbar1 />
        )
      }
      {children}
    </Fragment>
  )
}

const mapStateToProps = state => ({
  isAuthenticated: state.auth.isAuthenticated,
  reg_number: state.profile.reg_number,
  email: state.profile.email
})
export default connect(mapStateToProps, {check_authenticated, load_techer_user})(Layout)