import React, {useState, useEffect} from 'react';
import { connect } from 'react-redux';
import profile from '../../../Redux/Reducers/profile';
import { load_techer_user } from '../../../Redux/Actions/profile';
import '../css/TeacherCourse.css';
import axios from 'axios';
import noImage from '../images/no_img.jpg';
import {useParams, Link } from 'react-router-dom';
import AddBoxIcon from '@mui/icons-material/AddBox';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';

import {format, set} from 'date-fns';
import Swal from 'sweetalert2';
import { ButtonBase } from '@mui/material';



const TeacherCourse = ({load_techer_user, teacherId}) => {

    const {course_id} = useParams();
    const [courseData, setCourseData] = useState([])
    const [totalData, setTotalResult] = useState(0)

// Fetching the API Here
    useEffect(() => {
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/teacher-course/${teacherId}/`)
        .then((response) => {
            setCourseData(response?.data)
        })
        .catch((error) => {
            console.error(error)
        })
        // Get enrolled students
        
    }, [])

// Functionalities


const handleDelete = (course_id) => {
      Swal.fire({
        title: 'Delete', color: 'red',
        text: 'Are you sure you want to delete this topic',
        background: 'white',
        icon: 'warning',
        confirmButtonText: 'Delete',
        showCancelButton: true,
      })
      .then(result =>{
        if(result.isConfirmed){
            axios.delete(`${process.env.REACT_APP_LMS_BASE_URL}/lms/course-list/${course_id}/`)
            .then(res => {
                setCourseData(res?.data)
                setTotalResult(res?.data.length)
                console.log(res.data)
                if(res.status == 200){
                    Swal.fire('success', 'Course deleted')
                }
            })
            .catch(error => {
                Swal.fire('error', 'an Error occured, try again')
            })
        }
        else{
            Swal.fire('Quit', 'Operation canceled')
        }
      })

}

return(
        <div className='course11'>
        <div className='teacher__course'>
             <div className='course__header'>
                <h2>Loaded Courses </h2>
            </div>

            <div className='tables1'>
            {
                courseData.length != 0 ? 
                <table>
                <thead className='thead1'>
                    <tr>
                        
                        <th>
                            Course Topic
                        </th>
                        <th>
                            Enrolled Student
                        </th>
                        <th>
                            Course Image
                        </th>
                        <th>
                            Time uploaded
                        </th>
                        <th>
                            Action
                        </th>
                    </tr>
                </thead>
                {
                    courseData?.map((cos, index) => {
                        return( 
                    <tbody className='tbody1'>
                     <tr> 
                        
                            <td key={index}>
                                <Link className='topic_name' to={cos.id + `/` + `chapter`}> 
                                {cos.topic}
                                </Link>
                            </td>

                            <td>
                             <Link className="text-white" to={`enrolled_student/${cos.id}/`}>{cos.total_enrolled_student}</Link>   
                            </td>
                       
                        {
                           cos.course_image ?  <td> <img className='cos_image' src={cos.course_image} alt='' width="80px" /> </td> 
                           :  <td><img className='cos_image' src={noImage} alt="" width="80px" /> </td>
                        }
                        
                        <td>
                           {

                            format(new Date(cos.time), 'dd/MM/yyyy')

                            }
                        </td> 
                        <td>
                            <div className='butn'>
                            <span className='router__link'>
                            <Link to={`/add-chapter/` + cos.id}>
                            <button className='but btn2'><AddBoxIcon /></button>
                            </Link>

                                <Link to={`/add-course/edit/` + cos.id}>
                                <button style={{background:''}} className=' edit btn2'><EditIcon /></button>
                            </Link>                                     
                            </span>
                                <button onClick={handleDelete} className='but4 btn2'><DeleteIcon className='delete__icon' /></button>
                            </div>
                        </td>
                    </tr>
                </tbody>
                )
                    })
                }
                
                </table>
                :
                <span>
                     You have no course uploaded
                </span>
            }
            </div>
        </div>
           
        </div>
    )
}

const mapStateToProps = state => ({
    teacherId: state.profile.teacherId
})

export default connect(mapStateToProps, {load_techer_user})(TeacherCourse);