import React, {useState, useEffect} from 'react';
import '../Auth/CSS/Signup.css';
import '../Auth/CSS/Auth.css';
import axios from 'axios';
import { connect } from 'react-redux';
import {student_register} from '../Redux/Actions/auth';
import CSRFToken from '../Components/CSRFToken';
import Swal from 'sweetalert2'
import { Link, useNavigate } from 'react-router-dom';

const StudentRegister = ({student_register, error, success, loading}) => {
  const navigate = useNavigate();
const [ensure, setEnsure] = useState('')
  const [studentData, setStudentData] = useState({
  'username': '',
  'email': '',
  'password': '',
  're_password': '',
  'reg_no': '',
  })

  const handleChange = (event) => {
  setStudentData({
    ...studentData,
    [event.target.name]: event.target.value
  })
  }

  const {reg_no, email, username, password, re_password} = studentData;

  function handleSubmit(e) {
    e.preventDefault()
    try{
      if(re_password != '' && password != '' && username != '' && reg_no != ''){
        student_register(reg_no, email, username, password, re_password)
        setEnsure('')
      } else{
        //error
        setEnsure("No field should be empty")
      }
    
    }catch(err) {
      navigate('.')
     
    }
    } 
   
  useEffect(() => {
    if(success){
      Swal.fire({
        title: "Account created!",
        // icon: "error",
        toast: true,
        timer: 2500,
        position: "top-right",
        color: 'success',
      })
      navigate('/student-login')
    }
    
  },[success])
   
    return(
    <div className='nt-4 auth'>
        <div className='auth__container'>
            <div className="signup">
                <form onSubmit={handleSubmit} className='form'>
                 <CSRFToken />
                  <h3 className='form_header' >Sign Up Here</h3> <br />              
                    {
                    error ? <li className='erromsg'>{ error }</li> : ""
                    }
                    {
                      ensure ? <li className='erromsg last'>{ensure}</li> : ''
                    }
                  <label className='label1'>Registration number</label>
                  <label  className='label1 warn'>Registering someone else Reg. No. attracts account suspension</label>
                  <input onChange={handleChange} type="text" name="reg_no" value={reg_no} placeholder='imt/unn/b.sc/cos/year/reg' autoFocus={true}/>
                  <label className='label1'>Username</label>
                  <input onChange={handleChange} type="text" name="username" value={username}  placeholder='username' />
                  <label className='label1'>Email</label>
                  <input onChange={handleChange} type="email" name="email" value={email} placeholder='email' required={true} />
                  <label className='label1'>password</label>
                  <input onChange={handleChange} type="password" name="password" value={password} placeholder='password' />
                  <label className='label1'>Confirm password</label>
                  <input onChange={handleChange} type="password" name="re_password" value={re_password} placeholder='Re-enter your password' />
                  <button type="submit" disabled={loading} className='buttonL'>{ loading ? 'please wait...' : 'Sign up'}</button>
                </form>
                <div className='log'>
                <p>Already have an Account? <Link style={{textDecoration: "none"}} to="/student-login">Sign in</Link></p>
                </div>
            </div>
        </div>
    </div>
    )
}

const mapStateToProps = state => ({
  error: state.auth.error,
  success: state.auth.success,
  loading: state.auth.loading,
})
export default connect(mapStateToProps, {student_register})(StudentRegister)