import axios from "axios";
import Cookies from 'js-cookie'
import {
    LOAD_STUDENT_PROFILE_FAIL,
    LOAD_STUDENT_PROFILE_SUCCESS,
    LOAD_TEACHER_PROFILE_SUCCESS,
    LOAD_TEACHER_PROFILE_FAIL
} from './types';


export const load_techer_user = () => async dispatch => {
    const config = {
        headers: {
            'Accepts': 'application/json',
            'Content-Type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'),
        }
    }
    try{
        const res = await axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/account/teacher-profile/`, config)

        if(res.data.error){
            dispatch({
                type: LOAD_TEACHER_PROFILE_FAIL,
                payload: res.data.error,
            })
        }
        else{
            dispatch({
                type: LOAD_TEACHER_PROFILE_SUCCESS,
                payload: res.data
            })
        }
    }catch(error){
        // error
        dispatch({
            type: LOAD_TEACHER_PROFILE_FAIL,
        })
    }
}


export const student_profile = () => async dispatch => {
    const config = {
        headers: {
            'Accepts': 'application/json',
            'Content-type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'),
        }
    }
    try{
        const res = await axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/account/student-profile/`, config);
        if(res.data.error){
            dispatch({
                type: LOAD_STUDENT_PROFILE_FAIL,
            })
        }else{
            dispatch({
                type: LOAD_STUDENT_PROFILE_SUCCESS,
                payload: res.data
            })
        }
    }
    catch(error) {
        console.log(error)
        dispatch({
            type: LOAD_STUDENT_PROFILE_FAIL,
        })
    }
}