import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import Cookies from 'js-cookie';
import axios from 'axios';
import Navbar1 from './Navbar1';
import Card from 'react-bootstrap/Card'
import Button from 'react-bootstrap/Button';
import Courses from '../static/images/icon.jpg';
import {Link, useParams} from 'react-router-dom';
import Footer from './Footer';
import Slider from '../Slider/Slider';
import '../css/Home.css';
import CSRFToken from './CSRFToken';


const Favorites = ({studentId}) => {

const [courseData, setCourseData] = useState([])
const [favoriteCourse, setFavoriteCourse] = useState([])
const {course_id} = useParams()


useEffect(() => {


        const config = {
            headers : {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'X-CSRFToken': Cookies.get('csrftoken'),
            }
        }

        const body = {
            studentId: studentId,
        }

    try{
        axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-fav-course/`, {studentId: studentId}, config)
        .then(res => {
            setFavoriteCourse(res.data)
        })
        .catch(error => {
            console.log(error)
        })
    }
catch(error){
    console.log("This is the Error Now ", error)
}

},[course_id, studentId])

    return(
      <section className='Favorite'>
      <Slider />
      <div className='course__container' > 
        
            <div className='headings1'>
                <div className='header1'>
                    Favorite Courses
                </div>
            </div>
            <CSRFToken />
            
            <div className='course__card2'>
            {
                favoriteCourse?.map((fav, index) => {
                    return(
                    
                    <div className='main_contents'>
                        <Link to={`/detail/play/${fav.id}`}>
                            <video src={fav?.course.video} width='280'></video>
                            <p>{fav.course.title}</p> 
                        </Link> 
                    </div>
                    )
                } )
            }
            
            </div>
            
           <Footer />
        </div>
        
      </section>
        
    )
}
const mapStateToProps = state => ({
    studentId : state.profile.studentId
})
export default connect(mapStateToProps, {})(Favorites);