import React, { useEffect, useState } from 'react';
import {useParams, useNavigate } from 'react-router-dom';
import Cookies from 'js-cookie';
import TeacherHeader from './TeacherHeader';
import '../css/TeacerAddChapter.css';
import PosterImg from '../images/Iboadage.jpg';
import PostImg from '../images/cos.png';
import axios from 'axios'
import CSRFToken from '../../../Components/CSRFToken';
const BASEURL = 'http://127.0.0.1:8000/lms/'

const EditChapter = () => {
    const [fetcherror, setFetchError] = useState(false)
    const [succeeded, setSucceeded] = useState(false)
    const [videoError ,setVideoError] = useState(false)
    const [disabled, setDisabled] = useState(false)
    const [processing, setProcessing] = useState(false)
    const [videoUrl, setVideoUrl] = useState('')
    const [defaultVideoURL, setDefaultVideoURL] = useState('');

    const [chapterData, setChapterData] = useState({
        ref_course: '',
        title: '',
        video: defaultVideoURL,
        remark: '',
    })  
    // Fetching the previous data
    useEffect(() => {
       try{
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/chapter/${course_id}/edit`)
        .then((res) => {
            setChapterData({
                ref_course: res.data.ref_course.id,
                title: res.data.title,
                video: null,
                remark: res.data.remark,
            })
            setDefaultVideoURL(res.data.video)
            console.log('response is => ', res.data)
        })
       }catch(error){
            console.log(error)
        }

    }, [])

    const {course_id} = useParams()
    const navigate = useNavigate()

    const handleChange = (event) => {
        setChapterData({
            ...chapterData,
            [event.target.name]: event.target.value
        })
    }
    const handleFileChange = (event) => {
        // setChapterData({
        //     ...chapterData,
        //     [event.target.name]: event.target.files[0]
        // });
        // }
        const file = event.target.files[0];
        if(file){
            const fileURL = URL.createObjectURL(file)
            setDefaultVideoURL(fileURL)
            setChapterData({
                ...chapterData,
                video: file
            })

        }
    }


    const handleSubmit = (e) => {
        e.preventDefault();
        setProcessing(true)
        setDisabled(true)
        const formData = new FormData();
        formData.append('ref_course', chapterData.ref_course)
        formData.append('title', chapterData.title);
        formData.append('remark', chapterData.remark)

        if(chapterData.video){
            formData.append('video', chapterData.video);  
        }else{
            formData.append('video', defaultVideoURL); 
        }

        axios.put(`${process.env.REACT_APP_LMS_BASE_URL}/lms/chapter/${course_id}/edit`, formData, {
          headers: {
            'content-type' : 'multipart/form-data',
            'X-CSRFToken': Cookies.get('csrftoken')
          }
        })
        .then(res => {
            setChapterData(res.data)
            console.log(res.data)
            setSucceeded(true)
            setProcessing(false)
            navigate('/course-list/'+ chapterData.ref_course + '/chapter')
            //localhost:3000/course-list/3/chapter
        })
        .catch(error => {
            console.log(error)
            setSucceeded(false)
            setProcessing(false)
            setDisabled(false)
            setFetchError(true)
            setVideoError(error?.response?.data)
        })
    }  

console.log("ërror ", videoError)
  

    return(
        <div className='teacher_add_chapter'>
        <div className='page_body'>
             <div className='chapter_head'>
                <h2 className='h2'>Edit Chapters </h2>
            </div>
            <div className='section'>
              <div className='posters'>
                <img src={PostImg} alt="" />
                <img className="img1" src={PosterImg} alt="" />
              </div>
              <div className='form_section'>
              <h3 className='h3'><span className='info'>Warning! </span>Upload your video, specific to what you teach.</h3>
                <form className='.formik'>
                <CSRFToken />
                    { videoError?.video ? <p className='fetch__error'><strong>Please re-upload/edit the video or exit the page</strong></p> : ''}
                    
                    <label>chapter title </label>
                    <input onChange={handleChange} value={chapterData.title} type='text' name="title" />

                    <label>Video </label>
                    <input onChange={handleFileChange} type='file' accept="video/mp4" name="video" />
                    <div>
                        {defaultVideoURL && (
                           <video className='videos' width="200px" controls>
                                <source src={defaultVideoURL}  type='video/mp4'/>
                            </video>  
                        )}
                       
                    </div>
                    <label>Remark</label>
                    <textarea value={chapterData.remark} onChange={handleChange} name='remark'></textarea>
                      <button disabled={processing || disabled || succeeded} onClick={handleSubmit} className='butns'>
                       <span> {processing ? 'uploading... wait!' : "Upload" }</span> 
                    </button>
                    
                </form>
              </div>
            </div>
            
        </div>
            
        </div>
    )
}

export default EditChapter;