import React, { useState } from 'react';
import { connect } from 'react-redux';
import Cookies from 'js-cookie';
import Modal from 'react-modal';
import './StudentData/css/Modal.css';
import { Button } from '@mui/material';
import StarBorderIcon from '@mui/icons-material/StarBorder';
import StarIcon from '@mui/icons-material/Star';
import axios from 'axios';
import Swal from 'sweetalert2';
import CSRFToken from './CSRFToken';

function ModalDisplay({studentId, video, title, course_id, setRatingStatus, sendData}) {

    const student_id = localStorage.getItem('studentId');
    const [modalIsOpen, setModalIsOpen] = useState(false)
    const [hoverRating, setHoverRating] = useState(0)
    const [rating, setRating] = useState(1)
    const [review, setReview] = useState('');
    const [isRated, setIsRated ] = useState(false)


    const [ratingReview, setRatingReview] = useState({
        'course': course_id,
        'student': student_id,
        'review': review,
        'rating': rating,
    }) 

    const handleModalOpen = () => {
        setModalIsOpen(true)
    }
    console.log('rating =>', rating )

    const handleMouseOver = (index) => {
        setHoverRating(index + 1);
      };

    const handleMouseLeave = (() => {
    setHoverRating()
    })

    const handleClick = (index) => {
            /// axios request
            setRating(index + 1)
            console.log(index + 1)
    }
    const handleChange = (e) => {
        setRatingReview({
            ...ratingReview,
            [e.target.value]:e.target.name
        })
    }

    console.log(review)

    const handleSubmit = () => {
        // handle submission using axios
        const formData = new FormData();
        formData.append("course", course_id)
        formData.append("student", studentId)
        formData.append("rating", rating)
        formData.append("review", review)
        
        const config = {
            headers : {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'X-CSRFToken': Cookies.get('csrftoken'),
            }
        }

        axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/lms/course-rating/${course_id}/`, formData, config)
        .then(res => {
            Swal.fire({
                title: `You rated ${rating} thank you!`,
                icon: 'success',
                timer: 3000,
                position: 'top',
                width: '75%',
                height: '65%',
            })
            window.location.reload()
            
            setModalIsOpen(false);
            axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/rating-status/${studentId}/${course_id}`)
            .then(res => {
                // setRatingStatus(res.data)
                sendData(res.data)
            })
            .catch(error => {
                console.log(error)
            })
        })
       
        .catch(error => {
            console.log("post error => ", error)
        })
        
    }


  return (
  <span className='Modal'>
  <Modal isOpen={modalIsOpen} onRequestClose={() => setModalIsOpen(false)}>
    <CSRFToken />
    <span className='gen'> 
        <span className='modal__heading'>
            <i className='mui_btn'><Button style={{transition:'.5s ease-in'}} onClick={() => {setModalIsOpen(false )}}>Close</Button></i>
            <h2>Rate Video</h2>
         </span>
            <div className='modal__body'>
                <span className='vid__text'>{title}</span>
                <div className='star2'>
                <video src={video}  style={{marginRight:'.5rem'}}></video>
                 {
                    [...Array(5)].map((_, index) => {
                        return(
                            <>
                            <span key={index}
                            className={`star ${index < (hoverRating || rating) ? "hover" : ""}`}
                            onMouseOver={()=>handleMouseOver(index)}
                            onMouseLeave={handleMouseLeave}
                            onClick={() => setRating(index + 1)}
                            >
                                <StarIcon />

                            </span>
                            
                            </>
                             
                        )
                    })
                } 
                </div><p className='mt-1 text-success w-2' style={{fontSize:'1rem', fontWeight:'600', textAlign: 'center'}}>
                    {
                    rating <= 1 ?
                    <i>Default <code>{rating}</code> Star</i>
                    :
                   <strong>You are rating{''} <i className='text-dark' style={{fontWeight:'700'}}>{rating}</i> Stars</strong> 
                    }
                    </p>
                    
                <div className='review__text' >
                    <textarea placeholder='Review here' onChange={e => setReview(e.target.value)} value={review} autoFocus="tr" name="review" />
                </div>
        </div>
            <div className='btn__ui'><Button className="mui__button" onClick={handleSubmit}>Send Review</Button></div>
    </span> 
</Modal>
    <Button  className="mui__button"  onClick={handleModalOpen}>Rate Video</Button>
  </span>
    
  )
}

const mapStateToProps = state => ({
    studentId : state.profile.studentId
})
export default connect(mapStateToProps, {}) (ModalDisplay)