import React, { useState } from 'react';
import Sidebar from '../SideBarSection/Sidebar';
import '../css/settings.css';
import profile from '../images/agonizing jesus.png';
import EditIcon from '@mui/icons-material/Edit';

const Settings = () => {
    const [isinput, setIsinput] = useState(false)
    const [isinput1, setIsinput1] = useState(false)
    const [isinput2, setIsinput2] = useState(false)


    const handleInputToggle = (onAndOff) => {
        setIsinput(onAndOff)
    }

    const handleInputToggle1 = (onOf) => {
        setIsinput1(onOf)

    }

    const handleInputToggle2 = (onOf) => {
        setIsinput2(onOf)

    }
    
    return(
        <div className='settings'>
            

            <div className='setting__container'>
                <Sidebar className='sidebar'/>
            <div className='setting__div'>
                <h1 className='h1'>Profile Settings</h1>
                <div className='break'>
                </div>

                <div className='profile'>
                <ul className='list'>
                <div className='image'><img src={profile} alt="img" className='img' /></div>
                <li className='span inp'>Full Name: <strong> {!isinput ? <h4>Michael</h4> : "" }</strong>{ isinput ?<><input type='text' placeholder='Enter your full name'/> <button>submit</button></>  : ""} { isinput ? <button className="bg-danger text-white" onClick={()=>handleInputToggle(false)}>cancle</button> : <EditIcon onClick={()=> handleInputToggle(true) } />} </li>
                <li className='span inp'>Mobile Number: <strong>{ ! isinput1 ? <h4>0903784744</h4> : "" }</strong> {isinput1 ? <><input type='text' placeholder='Mobile number'/><button>submit</button> </> : ""} { isinput1 ? <button className="bg-danger text-white" onClick={() => handleInputToggle1(false)}>cancle</button> : <EditIcon  onClick={() => handleInputToggle1(true)} className='icon'/> }</li>
                <li className='span bg inp'>Reg. No. <input type='text' autoFocus="true" placeholder='Enter your School Reg. No.' /> <button>submit</button></li>
                <li className='span bg'>Course of study<strong>Computer Science</strong></li> 
                <li className='span inp'>Residential Address: <strong>{ ! isinput2 ? <h4>Address</h4> : "" }</strong> {isinput2 ? <><input type='text' placeholder='Address'/><button>submit</button> </> : ""} { isinput2 ? <button className="bg-danger text-white" onClick={() => handleInputToggle2(false)}>cancle</button> : <EditIcon  onClick={() => handleInputToggle2(true)} className='icon'/> }</li>  
                </ul>  
                </div>
            </div>
            </div>
            
        </div>
    )
}

export default Settings;