 export const check_authenticated = () => async dispatch => {

    const config = {
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'),
            'Authorization': Cookies.get('csrftoken')
            
        }
    }

    const body = JSON.stringify({
        'withCredentials': true
    });

    try{
        const res = await axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/account/check-authenticated/`, body, config)

        if(res.data.error || res.data.isAuthenticated === "error"){
            dispatch({
                type: IS_AUTHENTICATED_FAIL,
                payload: false
            })
        }else if(res.data.isAuthenticated === 'success'){
            dispatch({
                type: IS_AUTHENTICATED_SUCCESS,
                payload: true
            })

            dispatch({
                type: IS_AUTHENTICATED_STUDENT_SUCCESS,
                payload: true
            })

            dispatch(load_techer_user())
        }
        else{
            dispatch({
                type: IS_AUTHENTICATED_FAIL,
                payload: false
            })
            dispatch({
                type: IS_AUTHENTICATED_STUDENT_FAIL,
                payload: false
            })
            
        }

    } catch(error){
        dispatch({
            type: IS_AUTHENTICATED_FAIL,
            payload: false
        })
    }

 }

