export const student_register = (reg_no, email, username, password, re_password) => async dispatch => {
    dispatch({
        type: SUBMIT_START,
         })
    const config = {
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'), 
        }
    };
    const body = JSON.stringify({reg_no, email, username, password, re_password});
    

try{    
    const res = await axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/account/student-register/`, body, config);
    const {success, error} = res.data

    if(error){
        dispatch({
            type: STUDENT_REGISTER_FAIL,
            payload: error,
        })
    }
    else{
        dispatch({
            type: STUDENT_REGISTER_SUCCESS,
            payload: success,
        })
    }
}catch(error){
    dispatch({
        type: STUDENT_REGISTER_FAIL
    })
}
}

export const student_login = (reg_no, password) => async dispatch => {
    dispatch({
        type: SUBMIT_START,
         })
    const config = {
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken'),
        }
    }
    const body = JSON.stringify({reg_no, password})
        axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/account/student-login/`, body, config)
        .then((res) => {
                const {errorLogin, successLogin} = res.data
                if(res.data.error){
                    dispatch({
                        type: STUDENT_LOGIN_FAIL,
                        payload: res.data.error,
                    })
                    dispatch(student_profile())
                }else{
                    dispatch({
                        type: STUDENT_LOGIN_SUCCESS,
                        payload: res.data.success
                    })
                    dispatch(load_techer_user())
                }  
        })
        .catch(error => {
            dispatch({
                type: STUDENT_LOGIN_FAIL
            })
        })

}

