// Verify sent code
export const teacher_verify = (email, code, new_password, re_new_password) => async dispatch => {
    dispatch({
        type: SUBMIT_START
    })

    const config = {
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
        },
    }
    const body = JSON.stringify({email, code, new_password, re_new_password})


try{
     const res = await axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/account/teacher-verify-code-reset-password/`, body, config)
    const {error, success} = res.data;
    if(error){
        dispatch({
            type: TEACHER_VERIFY_RESET_PASSWORD_FAIL,
            payload: error,
        })
    }
    else if(success){
        dispatch({
            type: TEACHER_VERIFY_RESET_PASSWORD_SUCCESS,
            payload: success,
        })
    }
    else if(success){
        dispatch({
            type: RESEND_CODE
        })
    }
}catch(error){
    dispatch({
        type: TEACHER_VERIFY_RESET_PASSWORD_FAIL
    })
}
}

