export const logout = ()=> async dispatch => {
    dispatch({
        type: SUBMIT_START,
    })

    const config = {
        headers:{
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-CSRFToken': Cookies.get('csrftoken')
        }
    }

    const body = JSON.stringify({
        'withCredentials': true
    });
    try{
        const res = await axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/account/logout/`, body, config)
            const {success, error} = res.data
        if(error){
            dispatch({
                type: LOGOUT_FAIL,
                payload: error,
            })
        }else{
            dispatch({
                type: LOGOUT_SUCCESS,
                payload: success
            })
        }
    }
    catch(error){
        dispatch({
            type: LOGOUT_FAIL
        })
    }
}