import React, { useEffect, useState } from 'react';
import Sidebar from '../SideBarSection/Sidebar';
import Cookies from 'js-cookie';
import { connect } from 'react-redux';
import '../css/settings.css';
import profile from '../images/agonizing jesus.png';
import EditIcon from '@mui/icons-material/Edit';
import axios from 'axios';
import { resolvePath } from 'react-router-dom';
import CSRFToken from '../../../Components/CSRFToken';

const TeacherProfile = ({teacherId}) => {

    const [isinput, setIsinput] = useState(false)
    const [isinput1, setIsinput1] = useState(false)
    const [isinput2, setIsinput2] = useState(false)

    const [teacherDetails, setTeacherDetails] = useState('')


    const handleInputToggle = (onAndOff) => {
        setIsinput(onAndOff)
    }

    const handleInputToggle1 = (onOf) => {
        setIsinput1(onOf)

    }

    const handleInputToggle2 = (onOf) => {
        setIsinput2(onOf)

    }

    const handleCancle = (value) => {
        {
            if (value == ''){
                value = value
                alert("Invalid field")
            }
            else{
                setIsinput(false)
            }
            
        }
    }
    const [profileSetting, setProfileSetting] = useState({
        "full_name": "",
        'email': "",
        'qualification': "",
        'mobile_no': "",
        'address': "",
        'skills': "",
    })

const handleChange = (event) => {
    setProfileSetting({
        ...profileSetting,
        [event.target.name]:event.target.value
    })
}

useEffect(() => {
    axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/teachers/${teacherId}/`)
    .then(res => {
        setTeacherDetails(res.data.teacher_details)
        setProfileSetting({
            full_name: res.data.full_name,
            email: res.data.email,
            qualification: res.data.qualification,
            mobile_no: res.data.mobile_no,
            address: res.data.mobile_no,
            skills: res.data.skills
        })
})
    .catch(error => {
        console.log(error)
    })
},[])

console.log("Teacher ID ", teacherId)

const handleSubmit  = (event) => {
    const formSubmit = new FormData()
    formSubmit.append('full_name', profileSetting.full_name && ' ');
    formSubmit.append('email', profileSetting.email && ' ');
    formSubmit.append('teacher', teacherId);
    formSubmit.append('mobile_no', profileSetting.mobile_no && ' ');
    formSubmit.append('qualification', profileSetting.qualification && ' ');
    formSubmit.append('address', profileSetting.address && ' ');

    axios.put(`${process.env.REACT_APP_LMS_BASE_URL}/lms/teachers/${teacherId}/`, formSubmit, {
        headers: {
            'content-type': 'multipart/form-data',
            'X-CSRFToken': Cookies.get('csrftoken')
        }
    })
    .then(res => {
        setProfileSetting({
            'full_name': '',
            'email': '',
            'teacher': teacherId,
            'mobile_no': '',
            'qualification': '',
            'address': '',
        })
       
    })
    .catch(error => {
        console.log(error)
    })

}

console.log(profileSetting)
    return(
        <div className='settings'>
            

            <div className='setting__container'>
            <div className='setting__div'>
                <h1 className='h1'>Profile Settings</h1>
                <div className='break'>
                </div>

                <div className='profile'>
                <ul className='list'>
                <div className='image'><img src={profile} alt="img" className='img' /></div>
                <CSRFToken />
                <li className='span inp'>Full Name: <strong> {!isinput ?
                 <h4>{profileSetting.full_name}</h4> : "" }</strong>{ isinput ?<><input onChange={handleChange} type='text' name='full_name'
                  value={profileSetting.full_name} placeholder='Enter your full name'/> <button onClick={handleSubmit}>submit</button></>  : ""} 
                  { isinput ? <button className="bg-danger text-white" onClick={() => handleCancle(profileSetting.full_name)}>cancle</button> : 
                  <EditIcon onClick={()=> handleInputToggle(true) } />} </li>

                <li className='span inp'>Mobile Number: <strong>{ ! isinput1 ? <h4>{profileSetting.mobile_no}</h4> : "" }</strong> {isinput1 ? <><input onChange={handleChange}  type='text' name="mobile_no" value={profileSetting.mobile_no} placeholder='Mobile number'/><button>submit</button> </> : ""} { isinput1 ? <button className="bg-danger text-white" onClick={() => handleInputToggle1(false)}>cancle</button> : <EditIcon  onClick={() => handleInputToggle1(true)} className='icon'/> }</li>
                <li className='span bg inp'>Teacher ID. 2023005</li>
                <li className='span bg'>Teacher Course<strong>Computer Science</strong></li> 
                <li className='span inp'>Residential Address: <strong>{ ! isinput2 ? <h4>{profileSetting.address}</h4> : "" }</strong> {isinput2 ? <><input onChange={handleChange} type='text' name="address" value={profileSetting.address} placeholder='Address'/><button>submit</button> </> : ""} { isinput2 ? <button className="bg-danger text-white" onClick={() => handleInputToggle2(false)}>cancle</button> : <EditIcon  onClick={() => handleInputToggle2(true)} className='icon'/> }</li>
                <li className='span bg inp'>Email: <strong>{ ! isinput2 ? <h4>{profileSetting.email}</h4> : "" }</strong></li>  
                </ul>  
                </div>
            </div>
            </div>
            
        </div>
    )
}
const mapStateToProps = state => ({
    teacherId: state.profile.teacherId,
})
export default connect(mapStateToProps, {})(TeacherProfile);