import React, {useEffect, useState} from 'react';
import { connect } from 'react-redux';
import { student_verify, student_reset } from '../Redux/Actions/auth';
import CSRFToken from '../Components/CSRFToken';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../Auth/CSS/Signup.css';
import '../Auth/CSS/Auth.css';
import '../Auth/CSS/Login.css';
import Swal from 'sweetalert2';
import auth from '../Redux/Reducers/auth';
import { Button } from '@mui/material';


const StudentResetPassword = ({student_reset, serror, error, success, ssuccess, student_verify, verify, loading}) => {
    const navigate = useNavigate();
    const [studentLogin, setstudentLogin] = useState({
        'reg_no': '',
        'email': '',
        'code': '',
        'new_password': '',
        're_new_password': ''
    })
    const [perror, setPerror] = useState("")

    const {reg_no, email, code, new_password, re_new_password} = studentLogin;

    const handleChange = (event) => {
        setstudentLogin({
            ...studentLogin,
            [event.target.name]:event.target.value,
        })
    }
    const handleSubmit = (event) => {
        event.preventDefault();  
    try{  
        if(email != '' && reg_no != ''){
            setPerror("")
            student_reset(email, reg_no.toLowerCase())
         }
        else{
           setPerror("Cannot submit empty field(s)")
        }
    } catch(err){
        //error
    }
     
    } 

    const handleVerify = (event) => {
        event.preventDefault();  
    try{  
        if(email != '' && code != '' && new_password != '' && re_new_password != ''){
            setPerror("")
            student_verify(email, code, new_password, re_new_password)
         }
        else{
            setPerror("Cannot submit empty field(s)")
        }
    } catch(err){
        //error
    }
     }

    useEffect(() => {
       if(success){
        Swal.fire({
            title: 'Code sent!',
            toast: true,
            position: 'top',
            timer: 1000,
        })
        navigate('.')
        }
        
    },[success])

    useEffect(() => {
        if(ssuccess){
         Swal.fire({
             title: `${ssuccess}`,
             toast: true,
             position: 'top',
             timer: 1000,
         })
         navigate('/student-login')
         }
         
     },[ssuccess])



    console.log("Here it's happening" , serror)
 
    return(
    <div className='auth'>
        <div className="student__login">
            <h2>Forgotten Password</h2>
        </div>
        {
            !success ?
                <> 
                <div className='login__container'>
                    <form onSubmit={handleSubmit} className='form'>
                        <CSRFToken />
                        <label className='label' style={{fontSize:'1.3rem', marginBottom:'.8rem'}}>Verify It's You</label>
                        {
                            serror && <p className='ermsg'>{serror}</p> 
                        }
                        {
                            perror && <p className='ermsg'>{perror}</p>
                        }
                        <label className='label1'>Registation number</label>
                        <input onChange={handleChange} type="text" name='reg_no' value={reg_no} autoFocus={true} placeholder='' required={true}/>
                        <label className='label1'>Registered email</label>
                        <input onChange={handleChange} type="email" name='email' value={email} placeholder="" />
                        <p>
                            <input className="checkBox" type="checkbox" name="remember" value="Remember me" />Remember me
                        </p>
                        <button type='submit' disabled={loading} className='login__button'>{loading ? "wait "  :  "Send code" }</button>
                    </form>
                    <div className='log'>
                        <p> Help ? <Link to=".">Contact us </Link></p>
                        <p> Back to <Link to="/student-login"> Login </Link></p>
                    </div>
                </div>
                </>
                
            :
             <>
            <div className='login__container'>
                <form onSubmit={handleVerify} className='form'>
                    <label className='label' style={{fontSize:'1.3rem', marginBottom:'.8rem'}}>Verify It's You</label>
                    {
                            error && <p className='ermsg'>{error}</p> 
                        }
                        {
                            perror && <p className='ermsg'>{perror}</p>
                        }
                    <label className='label1'>Registered email</label>
                    <input onChange={handleChange} type="email" name='email' value={email} placeholder="" />
                    <label className='label1'>Enter Code</label>
                    <input onChange={handleChange} maxLength={6} style={{textAlign: 'center'}} type="text" name='code' value={code} placeholder="" />
                    <label className='label1'>New Password</label>
                    <input onChange={handleChange} type="password" name='new_password' value={new_password} placeholder="" />
                    <label className='label1'>Confirm new password</label>
                    <input onChange={handleChange} type="password" name='re_new_password' value={re_new_password} placeholder="" />
                    <p className='ptag'>
                        Didn't receive code? <Button>Resend</Button>
                    </p>
                    {
                        serror && <p className='ermsg' style={{color: "red"}}>{serror}</p> 
                    }
                    {
                        perror && <p className='ermsg'>{perror}</p>
                    }
                    <button type='submit' disabled={loading} className='login__button'>{loading ? "wait "  :  "Send code" }</button>
                </form>
                    <div className='log'>
                        <p> Help ? <Link to=".">Contact us </Link></p>
                        <p> Back to <Link to="/student-login"> Login </Link></p>
                    </div>
            </div>
            </>
        } 
    </div> 
    )
}
const mapStateToProps = state => ({
    serror: state.auth.serror,
    success: state.auth.success,
    ssuccess: state.auth.ssuccess,
    loading: state.auth.loading,
    verify: state.auth.verify,
    error: state.auth.error,
})
export default connect(mapStateToProps, {student_reset, student_verify})(StudentResetPassword)
