import { 
    LOAD_STUDENT_PROFILE_FAIL,
    LOAD_STUDENT_PROFILE_SUCCESS,
    LOAD_TEACHER_PROFILE_FAIL,
    LOAD_TEACHER_PROFILE_SUCCESS,
 } from "../Actions/types";



 const initialState = {
    error: '',
    reg_number: '',
    username: '',
    email: '',
    studentId: '',
    teacherId: '',
    course: '',
    is_student: false,
    is_teacher: false,
 }


export default function(state=initialState, action){
    const {type, payload} = action;

    switch (type) {
        case LOAD_TEACHER_PROFILE_SUCCESS:
            return{
                ...state,                                                                                                                                       
                username: payload.username,
                email: payload.teacher_profile.email,
                teacherId: payload.teacherId,
                course: payload.teacher_profile.course,
                is_teacher: payload.teacher_profile.is_teacher,
            }

        case LOAD_TEACHER_PROFILE_FAIL:
            return{
                ...state,
                username: '',
                email: '',
                teacherId: ''
            }

        case LOAD_STUDENT_PROFILE_SUCCESS:
            return{
                ...state,
                username: payload.username,
                reg_number: payload.student_profile.reg_no,
                studentId: payload.studentId,
                is_student: payload.student_profile.is_student,
            }

        case LOAD_STUDENT_PROFILE_FAIL:
            return{
                ...state,
                username: '',
                reg_number: '',
            }
        default:
            return state;
    }
}
