import { 
    STUDENT_REGISTER_SUCCESS,
    STUDENT_REGISTER_FAIL,
    STUDENT_LOGIN_FAIL,
    STUDENT_LOGIN_SUCCESS,
    STUDENT_RESET_PASSWORD_SEND_CODE_FAIL,
    STUDENT_RESET_PASSWORD_SEND_CODE_SUCCESS,
    STUDENT_VERIFY_RESET_PASSWORD_FAIL,
    STUDENT_VERIFY_RESET_PASSWORD_SUCCESS,
    SUBMIT_START,
    TEACHER_REGISTER_FAIL,
    TEACHER_REGISTER_SUCCESS,
    TEACHER_LOGIN_FAIL,
    TEACHER_LOGIN_SUCCESS,
    TEACHER_RESET_PASSWORD_SEND_CODE_FAIL,
    TEACHER_RESET_PASSWORD_SEND_CODE_SUCCESS,
    TEACHER_VERIFY_RESET_PASSWORD_SUCCESS,
    TEACHER_VERIFY_RESET_PASSWORD_FAIL,
    RESEND_CODE,
    IS_AUTHENTICATED_SUCCESS,
    IS_AUTHENTICATED_FAIL,
    IS_AUTHENTICATED_STUDENT_FAIL,
    IS_AUTHENTICATED_STUDENT_SUCCESS,
    LOGOUT_FAIL,
    LOGOUT_SUCCESS

 } from "../Actions/types";



 const initialState = {
    error: '',
    serror: '',
    ssuccess: '',
    success: '',
    successLogin: '',
    errorLogin: '',
    loading: false,
    // Application level states
    IsAuthenticated: false,
    IsAuthenticated_student: false,
    username: '',
    email: '',
    studentId: '',
    teacherId: '',
    resend: null,
    verify: null,
 }

export default function(state=initialState, action){
    const {type, payload} = action;
    switch (type) {
        case SUBMIT_START:
            return {
                ...state,
                loading: true,
                error: '',
                errorLogin: '',
                serror: '',
            }
        case IS_AUTHENTICATED_SUCCESS:
        case IS_AUTHENTICATED_FAIL:
            return{
                ...state,
                IsAuthenticated: payload,
                IsAuthenticated_student: payload,
            }

        case IS_AUTHENTICATED_STUDENT_SUCCESS:
            return{
                ...state,
                IsAuthenticated_student: true,
                IsAuthenticated: false
            }

        case IS_AUTHENTICATED_STUDENT_FAIL:
            return{
                ...state,
                IsAuthenticated_student: false,
                IsAuthenticated: false
            }

        case STUDENT_REGISTER_SUCCESS:
            return {
                ...state,
                IsAuthenticated: false,
                IsAuthenticated_student: false,
                success: payload,
                loading: false
            }
        case STUDENT_REGISTER_FAIL:
            return {
                ...state,
                IsAuthenticated_student: false,
                error: payload,
                loading: false
            }
        case STUDENT_LOGIN_SUCCESS:
            return{
                ...state,
                successLogin: payload,
                IsAuthenticated_student: true,
                IsAuthenticated: false,
                loading: false
            }
        case STUDENT_LOGIN_FAIL:
            return{
                ...state,
                errorLogin: payload,
                IsAuthenticated: false,
                IsAuthenticated_student: false,
                loading: false
            }
            /// Teacher 
        case TEACHER_REGISTER_FAIL:
            return{
                ...state,
                loading: false,
                error: payload,
                IsAuthenticated: false,
                IsAuthenticated: false,
            }

        case TEACHER_REGISTER_SUCCESS:
            return{
                ...state,
                loading: false,
                IsAuthenticated: false,
                IsAuthenticated_student: false,
                success: payload,
            }
        case TEACHER_LOGIN_FAIL:
            return{
                ...state,
                IsAuthenticated: false,
                IsAuthenticated_student: false,
                errorLogin: payload,
                loading: false,
            }

        case TEACHER_LOGIN_SUCCESS:
            return{
                ...state,
                IsAuthenticated: true,
                loading: false,
                successLogin: payload,
                IsAuthenticated_student: false,
            }

        case TEACHER_RESET_PASSWORD_SEND_CODE_FAIL:
            return{
                ...state,
                IsAuthenticated: false,
                loading: false,
                error: payload,
                resend: false,
                loading: false,
            }

        case TEACHER_RESET_PASSWORD_SEND_CODE_SUCCESS:
            return{
                ...state,
                IsAuthenticated: false,
                loading: false,
                success: payload,
                resend: false,
            }
        
        case TEACHER_VERIFY_RESET_PASSWORD_SUCCESS:
            return{
                ...state,
                IsAuthenticated: false,
                success: payload,
                loading: false,
                resend: false,
                verify: true,
                
            }
        case TEACHER_VERIFY_RESET_PASSWORD_FAIL:
            return{
                ...state,
                IsAuthenticated: false,
                error: payload,
                loading: false,
                resend:  false,
                verify: false,
            }

            // Student Verifications
        case  STUDENT_RESET_PASSWORD_SEND_CODE_FAIL:
            return{
                ...state,
                IsAuthenticated_student: false,
                serror: payload,
                loading: false,
                verify: false,
            }
        case STUDENT_RESET_PASSWORD_SEND_CODE_SUCCESS:
            return{
                ...state,
                IsAuthenticated_student: false,
                IsAuthenticated: false,
                success: payload,
                loading: false,
                verify: false,
            }

        case STUDENT_VERIFY_RESET_PASSWORD_FAIL:
            return{
                ...state,
                IsAuthenticated_student: false,
                IsAuthenticated: false,
                error: payload,
                loading: false,
                verify: false,
            }
        case STUDENT_VERIFY_RESET_PASSWORD_SUCCESS:
            return{
                ...state,
                IsAuthenticated_student: false,
                loading: false,
                ssuccess: payload,
            }
        
        case LOGOUT_SUCCESS:
            return{
                ...state,
                IsAuthenticated: false,
                IsAuthenticated_student: false,
                username: '',
                teacherId: '',
                loading: false
            }
        case LOGOUT_FAIL:
            return{
                ...state,
                loading: false,
            }
        default:
            return state;
    }
}
