import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import { check_authenticated } from '../Redux/Actions/auth';

import axios from 'axios';
import Navbar1 from './Navbar1';
import Card from 'react-bootstrap/Card'
import Button from 'react-bootstrap/Button';
import Courses from '../static/images/icon.jpg';
import {Link, useNavigate} from 'react-router-dom';
import Footer from './Footer';
import Slider from '../Slider/Slider';
import '../css/Home.css';



// Urls fetching base
const Home = ({IsAuthenticated_student, check_authenticated}) => {
const [courseData, setCourseData] = useState([])
const [courseId, setCourseId] = useState(0)
const [chpt, setChpt] = useState([])

const navigate = useNavigate()

useEffect(() => {
    if(IsAuthenticated_student){
        navigate('')
    }
    else{
        navigate('/student-login')
    }
},[IsAuthenticated_student])

useEffect(() => {
  axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/` + 'courses/?result='+ 8)
  .then((res) =>{
    setCourseData(res.data)
    setCourseId(res.data)
    console.log(res.data)
  })
  .catch(error => {
    console.log(error.data)
  })
  // 
  axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/chapter/${2}/`)
  .then(res => (
      setChpt(res.data)
  ))
  .catch(err => {
      console.log(err.code)
  })

  console.log("HEER ==> ", courseId)
},[])

    return(
        <div>
            <Slider />

        <div className='course__container' >
            <div className='headings1'>
                <div className='header1'>
                    Course Lists
                </div>
                <div className='header2'>
                view all
                </div>
            </div>
            
            <div className='course__card2'>
            {
                courseData.map((cos, index) => {
                    return(
                    
                        <div className='main_contents'>
                           <Link to={`/detail/${cos.id}`}>
                                <img src={cos.course_image} alt='' width='500px' />
                                <p>{cos.topic}</p> 
                             </Link> 
                    </div>
                    )
                } )
            }    
            </div>
            <div className="latest__course">
                <div className='headings2'>
                    <div className='header11'>
                        Latest Course
                    </div>
                    <div className='header21'>
                    view all
                    </div>
                </div>            
            </div>
            
           
        </div>
    </div>
    )
}

const mapStateToProps = (state) => ({

    IsAuthenticated_student : state.auth.IsAuthenticated_student

})
export default connect(mapStateToProps, check_authenticated)(Home);