import React, {useEffect, useState } from 'react';
import './css/TeacherRegister.css'
import { Link, useNavigate } from 'react-router-dom';
import { connect } from 'react-redux';
import { teacher_register } from '../../Redux/Actions/auth';
import axios from 'axios';
import Swal from 'sweetalert2';
import CSRFToken from '../../Components/CSRFToken';

const TeacherRegister1 = ({teacher_register, loading, error, success}) => { 
    const [regError, setRegError] = useState('')
    const navigate = useNavigate()
    const [teacherData, setTeacherData] = useState(
        {
            'username': '',
            'email': '',
            'course': '',
            'password': '',
            're_password': '',
        }
    )
   const handleChange = (event) => {
        setTeacherData({
            ...teacherData,
            [event.target.name]:event.target.value
        });
    }

    const {username, email, course, password, re_password} = teacherData;

   const handleSubmit = (event) =>{
        event.preventDefault()
        try{
            if(password != "" && re_password != '' &&  email != '' && course != '' && username != ''){
                setRegError('')
                teacher_register(email, username, course, password, re_password)
            }
            else{
                setRegError('Cannot submit empty field(s)')
            }
        }catch(error){
        }
   }

   useEffect(() => {
    if(success){
        Swal.fire({
            position: 'top-right',
            title:  `Successful!`,
            timer: 2000,
            text: "Redirecting....",
            
        })
        navigate('/teacher-login')
    }
   },[success])
      
   console.log("==== > ", success)
    return(
        <div className='teacher__auth'>
          <div className='teacher__register'>
            <div className='register__card'>
                <h2 className='h2'> Register a Teacher Account</h2>
                <form onSubmit={handleSubmit} className='teacher_form'>
                    <CSRFToken />
                    {
                        error ? <p>{error}</p> : ''
                    }

                    {
                        regError ? <p>{regError}</p> : ""
                    }
                    <div className='input_wrapper1 input'>
                        <label className='label2'>Username</label>
                        <input className='input' name='username' onChange={handleChange} value={username} type='text' placeholder="" autoFocus={true} />
                    </div>
                    <div className='input_wrapper1 input'>
                        <label className='label2'>Email</label>
                        <input className='input' name='email' onChange={handleChange} value={email} type='email' required={true} placeholder='' />
                    </div>
                    <div className='input_wrapper1'>
                    <label className='label2'>Teaching Course</label>
                        <select onChange={handleChange} value={course} className='select' height="100px 1"  name="course" id="car">
                        <option className='option'>Select Option</option>
                        <option height="" className='option' >Python Programming</option>
                        <option className='option'>History Education</option>
                        <option className='option'></option>
                    </select>
                    </div>

                    <div className='input_wrapper1 input'>
                        <label className='label2'>Password</label>
                        <input className='input' name='password' onChange={handleChange} value={password} type='password' placeholder='' />
                    </div>
                    <div className='input_wrapper1 input'>
                        <label className='label2'>Confirm password</label>
                        <input className='input' name='re_password' onChange={handleChange} value={re_password} type='password' placeholder='' />
                    </div>
                    <button disabled={loading} className='btsub' type='submit'>{ loading ? "processing..." : "SUMBIT" }</button>  
                </form>
                <div className='register'>
                        <p>Already a registered staff? <Link to='/teacher-login' >Log-in here</Link></p>
                        <p>Need any Help? <Link to=".">Contact us</Link> </p>
                </div>
            </div>
        </div>  
        </div>
        
    )
}

const mapStateToProps = state => ({
    loading: state.auth.loading,
    error: state.auth.error,
    success: state.auth.success
})
export default connect(mapStateToProps, {teacher_register})(TeacherRegister1);