import React, {useState, useEffect} from 'react';
import '../Auth/CSS/Signup.css';
import axios from 'axios';
import { Link, useNavigate } from 'react-router-dom';

const Login = () => {
const [noMatch, setNoMatch] = useState(false);
const BASE_URL = 'http://127.0.0.1:8000';

const navigate = useNavigate();

  const [studentData, setStudentData] = useState({
    'full_name': '',
    'email': '',
    'password': '',
    'password2': '',
    'interested_course':'',
    'status': '',
    'admission_letter': '',
  })

  const handleFileChange = (event) => {
    setStudentData({
      ...studentData,
      [event.target.name]: event.target.files[0]
    })
  }

  const handleChange = (event) => {
    setStudentData({
      ...studentData,
      [event.target.name]: event.target.value
    })
  }

  console.log(studentData)


  function handleSubmit(e) {
    e.preventDefault()
    const studentFormData = new FormData();
    studentFormData.append("full_name", studentData.full_name)
    studentFormData.append("admission_letter", studentData.admission_letter)
    studentFormData.append("email", studentData.email);
    studentFormData.append("password2", studentData.password2)
    studentFormData.append("password", studentData.password)
    studentFormData.append("interested_course", studentData.interested_course)
   
      axios.post(BASE_URL +'/lms/student/list/create/', studentFormData)
        .then(res => {
          setStudentData({
            "full_name": '',
            'email': '',
            'password': '',
            'password2': '', 
            'interested_course': '',
            'status': 'success',
            'admission_letter': ''
          })
          navigate('login')
        })
        .catch(error => {
          console.log(error)
          setStudentData({'status': 'An error occured!'})
        })
  }




    return(
      
    <div className="signup">
          <div className='form'>
            <h3 className='form_header'>Sign Up Here</h3> <br />
            <label className='label1'>admission letter</label>
              <input onChange={handleFileChange} type="file" accept=".docs, .pdf, .txt" name="admission_letter" placeholder='' />
             <input onChange={handleChange} type="text" name="full_name"  placeholder='Enter your full name' />
            <input onChange={handleChange} type="email" name="email" placeholder='name@domain.com' />
            <textarea className='textarea' onChange={handleChange} type="text" name="interested_course" placeholder='your course here' />
            <input onChange={handleChange} type="password" name="password" placeholder='password' />
            <input onChange={handleChange} type="password" name="password2" placeholder='Re-enter your password' />
            <button onClick={handleSubmit} className='bttn'>Sign up</button>
          </div>
          <div className='log'>
            <p>Already have an Account? <Link style={{textDecoration: "none"}} to="/auth/login">Login in</Link></p>
          </div>
    </div>
    )
   
}

export default Login;