import React, {useEffect, useState} from 'react';
import { connect } from 'react-redux';
import { student_login } from '../Redux/Actions/auth';
import CSRFToken from '../Components/CSRFToken';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../Auth/CSS/Signup.css';
import '../Auth/CSS/Auth.css';
import '../Auth/CSS/Login.css';
import Swal from 'sweetalert2';
import auth from '../Redux/Reducers/auth';


const StudentLogin = ({student_login, errorLogin, IsAuthenticated_student, successLogin, loading}) => {
    const navigate = useNavigate();
    const [studentLogin, setstudentLogin] = useState({
        'reg_no': '',
        'password': '',
    })
    const [perror, setPerror] = useState("")

    const {reg_no, password} = studentLogin;
    const handleChange = (event) => {
        setstudentLogin({
            ...studentLogin,
            [event.target.name]:event.target.value,
        })
    }
    const handleSubmit = (event) => {
        event.preventDefault();  

    try{  
        
        if(password == ''){
            setPerror("Password field cannot be empty")
         }
        else{
            setPerror('')
            student_login(reg_no.toLowerCase(), password)
            if(successLogin){
            Swal.fire({
                title: `${successLogin}`,
                timer: 2000,
                color: 'success',
                position: 'top-right',
                toast: true,
            })
        } 
        }
    } catch(err){
        //error
    }
     } 


    useEffect(() => {
       if(IsAuthenticated_student){
        navigate('/dashboard')
        successLogin = ''
        }
        
    },[IsAuthenticated_student])
 
    console.log("check auth, ", IsAuthenticated_student)
    return(
    <div className='auth'>
        <div className="student__login">
            <h2>Learn Today, Earn Tommorrow</h2>
        </div>
        <div className='login__container'>
            <form onSubmit={handleSubmit} className='form'>
                <CSRFToken />
                <label className='label'>Sign In</label>
                <input onChange={handleChange} type="text" name='reg_no' value={reg_no} autoFocus={true} placeholder='Registration number' required={true}/>
                <input onChange={handleChange} type="password" name='password' placeholder="password" />
                <p>
                    <input className="checkBox" type="checkbox" name="remember" value="Remember me" />Remember me
                </p>
                {
                    errorLogin ? <p className='ermsg'>{errorLogin}</p> : ""
                }
                {
                    perror ? <p className='ermsg'>{perror}</p> : ""
                }
                <button type='submit' disabled={loading} className='login__button'>{loading ? "checking creden... "  :  "login" }</button>
            </form>
                <div className='log'>
                    <p> Don't have an account yet? <Link to="/student-register">Sign Up here</Link></p>
                    <p> Forgotten password? <Link to="/student-reset-password">Click here</Link></p>
                </div>
        </div> 
    </div>
    )
}
const mapStateToProps = state => ({
    errorLogin: state.auth.errorLogin,
    successLogin: state.auth.successLogin,
    IsAuthenticated_student: state.auth.IsAuthenticated_student,
    loading: state.auth.loading,
})
export default connect(mapStateToProps, {student_login})(StudentLogin)