import React, {useState, useEffect} from 'react';
import { Form, Link, useParams } from 'react-router-dom';
import axios from 'axios';
import CourseChapter from '../Dashboard/Components/TeacherDashboard/CourseChapter';
import Modal from 'react-modal';
import { Button } from '@mui/material';
import GppGoodIcon from '@mui/icons-material/GppGood';
import StarHalfIcon from '@mui/icons-material/StarHalf';
import StarBorderIcon from '@mui/icons-material/StarBorder';
import StarIcon from '@mui/icons-material/Star';
import ModalDisplay from './ModalDisplay';
import { set } from 'date-fns';
import Swal from 'sweetalert2';




const VideoPlayer = ({topic, teacher, category, favorite, chaptVideo, chapters, video, teacherId, enrolled}) => {
    const [chapterData, setChaperData] = useState([]);
    const [videoPlayer, setVideoPlayer] = useState([]);
    const student_id = localStorage.getItem('studentId');
    const {course_id} = useParams();
    const [ratingStatus, setRatingStatus] = useState('')
    const [rateAverage, setRateAverage] = useState("")
    const [childIsRated , setChildIsRated] = useState('')
    const [percentage, setPercentage] = useState([])
    const [favoriteCourse, setFavoriteCourse] = useState("")
    const [fav, setFav] = useState([])


    // console.log("Enrolled student ? =>", enrolled.enrolled)
    console.log("from child is rated")
    useEffect(() => {
            axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/chapter/${course_id}/edit`)
            .then(res => {
                setChaperData(res.data)
                console.log('chapters => ', res.data.video)
            })
            .catch(error => {
                console.log(error)
            })
            axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/rating-status/${student_id}/${course_id}`)
            .then(res => {
                setRatingStatus(res.data)
                console.log("HAS RATEDD ", res.data)
            })
            .catch(error =>{
                console.log(error)
            })
     // Fetch for rating average
            axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/course-list/chapter/${course_id}/`)
            .then(res => {
                setRateAverage(res.data)
                console.log("Rating average ===>", res.data)
                setPercentage((res.data.average_rating.rating__avg) / 5 * 100)
            })
            .catch(error => {
                console.log(error)
            })

    }, [])
    
    const handleFavoriteAdd = (e) => {
        const formData = new FormData();
        formData.append('course', course_id)
        formData.append('student', student_id)
        formData.append('status', true)
        try{
            axios.post(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-favorite-course/${student_id}/${course_id}/`, formData, {
                headers: {
                    "content-type": "multipart/form-data",
                }
            })
            .then(res => {
                setFavoriteCourse("success")
                Swal.fire({
                    title: "Added to Favorite",
                    icon: "success",
                    toast: true,
                    timer: 10000,
                    position: "top-right",
                })
                axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/student-favorite-course/${student_id}/${course_id}/`)
                .then(res => {
                    setFav(res.data)
                })
                .catch(err => {
                    // error
                })
            }).catch(error => {
                Swal.fire({
                    title: "Huh! Something went wrong",
                    // icon: "error",
                    toast: true,
                    timer: 3000,
                    position: "top-right",
                })
                console.log("Error ", error.code)
            })
        }catch(error){
            console.log("Error ", error.code)
        }
    }

// This is called "Callback Function" it will be passed to the child component as a prop

    const handleChildStateData = (data) => { 
        setChildIsRated(data);
    }

    console.log("What is here ==> ", chapterData)
    return(
        
        <div id={`video/ ${chapterData.id}`}  className='video__container1'>

                <div className='video__tag'>
                    {chapterData.id !== 1 ? <StarHalfIcon /> : ""  }
                {
                    chapterData.id !== 1 ? <img src="" /> :
                     <video id={`detail/${chapterData.id}`} src={chapterData.video} index={CourseChapter.id} className='videos' controls>
                    </video>
                   
                }
                 
                <p>{chapterData.title}</p>
            
            </div>
            
            <div className='course__details'>
                <div className='titles'>
                    <h1>{category} </h1>
                <h2>{topic}</h2></div>
                <div className='others'>
                    {
                        enrolled.enrolled ?
                        <>
                         <ul>
                        <li>Course by: <Link to={`/teacher/${course_id}`}><span style={{color: 'rgb(9, 90, 165'}}>   {teacher} </span></Link></li>
                        <li>Course Duration: <span>Time here</span></li>
                        {percentage >= 90 && 
                        <li className='rate__95'>Rating:<i style={{color:"black", padding: "0rem 0 .5rem .5rem"}}>
                            {rateAverage.average_rating.rating__avg}/5<StarIcon /></i>
                            <i style={{paddingLeft:".5rem,", color: "orange"}}>{" "}{percentage}%</i>
                        </li>
                        } 
                        
                        {
                            ratingStatus.hasRated || childIsRated.hasRated ? 
                            
                          <p className='gpp'><GppGoodIcon /> <code>Rated!</code></p> 
                          :
                        <p>
                     <ModalDisplay video={chapterData.video} title={chapterData.title} course_id={course_id} 
                            setRatingStatus={setRatingStatus} sendData={handleChildStateData} />
                        </p>
                        }
                        
                         
                        </ul>
                        <article>
                        <h2>Teacher Remarks</h2>
                        <p>{chapterData.remark}</p>
                    </article>
                        </>
                       
                    :
                    <ul>
                        <li>Enroll course below </li>
                    </ul>
                    }
                    
                    

                </div>
            </div>
        </div>
    )
}

export default VideoPlayer;