import React, { useEffect, useState } from 'react'
import TeacherHeader from './TeacherHeader'
import { Avatar } from '@mui/material'
import './css/ReviewPage.css';
import axios from 'axios';
import { useParams } from 'react-router-dom';

function ReviewPage() {
    //Constants
    const [reviews, setReviews] = useState([])
    let [isReview, setIsReview] = useState(false)
    const BASE_URL = 'http://127.0.0.1:8000/lms'
    const {course_id} = useParams()


    useEffect(() => {
        axios.get(`${process.env.REACT_APP_LMS_BASE_URL}/lms/course-rating/chapter/${course_id}/`)
        .then(res => {
            {
                res.data.length == 0 ? setIsReview(true) :
                setReviews(res.data) 
            }
            console.log(res.data)
        })
        .catch(error => {
            console.log(error)
        })
    },[])

  return (
    <div className='reviewPage'>
       <div className='student__review'>
        {
            reviews.map(review => {
                return(
                    <>
            {
                reviews.length == 0 ?
                <table>
                    <thead>
                        <th><Avatar /> <h5>No body yet</h5> <h6>!</h6></th>
                    </thead>

                    <tbody>
                        <td>
                        <p>Sorry, No review yet</p>
                        </td>
                    </tbody>
                </table>
                :
                <table>
                    <thead>
                        <th><Avatar /> <h5>{review.student.full_name}</h5> <h6>{review.student.email}</h6></th>
                    </thead>

                    <tbody>
                        <td>
                        {review.review == '' ? <code style={{fontSize:'1rem'}}>No comment</code> : <p>{review.review}</p>}
                        </td>
                    </tbody>
                </table>
            }
        </>
                )
            })
        }
          </div>
    </div>
  )
}

export default ReviewPage