import React, { useEffect, useState } from 'react';
import './css/TeacherLogin.css';
import { Link, useNavigate } from 'react-router-dom';
import { connect } from 'react-redux';
import { teacher_reset, teacher_verify } from '../../Redux/Actions/auth';
import axios from 'axios';
import Swal from 'sweetalert2';
import { Button } from '@mui/material';
import CSRFToken from '../../Components/CSRFToken';

const TeacherForgottenPassword = ({teacher_reset, teacher_verify, verify, error, success, loading}) => {
    const navigate = useNavigate()
    const [loginError, setLoginError] = useState('')

    const [teacherLoginData, setTeacheerLoginData] = useState({
        'email': '',
        'code': '',
        'new_password': '',
        're_new_password': '',
    })


    const handleChange = (event) => {
        setTeacheerLoginData({
            ...teacherLoginData,
            [event.target.name]: event.target.value
        })
        
    }

const {email, code, new_password, re_new_password} = teacherLoginData

const handleSubmit = (event) => {
    event.preventDefault()
    try{

    
    if(email != ''){
        setLoginError('')
        teacher_reset(email)
        //
    }
    else{
        setLoginError("Please provide your email")
    }
    }catch(eror){
        // Sinet
    }
}

const handleVerifySubmit = (event) => {
    event.preventDefault()
    if(email != '' && code != '' && new_password != '' && re_new_password != ''){
        setLoginError('')
        teacher_verify(email, code, new_password, re_new_password)
        //
    } else{
        setLoginError("Field(s) cannot be empty")
    }
    }


useEffect(() => {
    if(success){
        Swal.fire({
            title: "Sent successfully!",
            timer: 3000,
            
        })
        navigate('.')
    }
},[success]) 

useEffect(() => {
    if(verify){
        Swal.fire({
            title: "Password reset successfully!",
            timer: 3000,
            text: "redirecting"
        })
        navigate('/teacher-login')
    }
},[success])    

 
    return(
    <div className='teacher__auth'>
        <div className="teacher__login" style={{margin: '4rem auto'}}>
            <div className='heading2'>
                <h2> Forgotten Password</h2>
            </div>
            <div className='login__card'>
                <div className="card__heading">
                    <h1 className='h1'>Reset Password</h1>
                
                            {
                                loginError && <p className='errorLogin'>{loginError}</p>
                             }
                            {
                                error ? <p className='errorLogin'>{error}</p> : ''
                             }
                        
                        {
                            !success  ?
                                <form  onSubmit={handleSubmit} className='form'> 
                                <CSRFToken />
                                <div className='input_wrapper input'>
                                    <label className='label2'>Enter your registered email</label>
                                    <input className='input' name='email' onChange={handleChange} value={email} style={{fontSize:'1rem'}} type='email' placeholder='' autoFocus={true} />          
                                </div>
                                <button className='bttn' disabled={loading} type='submit'>{loading ? 'Sending, wait... ' : 'Send code' }</button>
                                 </form>
                            :
                                <form  onSubmit={handleVerifySubmit} className='form'>
                                    <CSRFToken />
                                <div className='input_wrapper input'>
                                    <label className='label2'>Enter your email again</label>
                                    <input className='input' name='email' onChange={handleChange} value={email} type='email' placeholder='' autoFocus={true} />          
                                </div>
                                <div className='input_wrapper input'>
                                    <label className='label2'>Enter Code</label>
                                    <input className='input' name='code' onChange={handleChange} maxLength={8} style={{textAlign: 'center'}} value={code} type='text' placeholder='' autoFocus={true} />          
                                </div>
                                <div className='input_wrapper input'>
                                    <label className='label2'>New password</label>
                                    <input className='input' name='new_password' onChange={handleChange} value={new_password} type='password' placeholder='' autoFocus={true} />          
                                </div>
                                <div className='input_wrapper input'>
                                    <label className='label2'>Confirm new password</label>
                                    <input className='input' name='re_new_password' onChange={handleChange} value={re_new_password} type='password' placeholder='' autoFocus={true} />          
                                </div>
                                 <button className='bttn' disabled={loading} type='submit'>{loading ? 'Verifying, wait... ' : 'Verify' }</button>
                                 
                                 <div className='register'>
                                    <p>Didn't receive code? {" "} <Button onClick={handleSubmit}>Resend code</Button> </p>
                                </div>
                                </form>
                        }
                        
                    <div className='register'>
                        <p>Back to  {""}<Link to="/teacher-login">login</Link></p>
                        <p>Help? {""}<Link to="/teacher-login">Click here</Link></p>
                    </div>
                </div>
            </div>
        </div>
    </div>
)      
}

const mapStateToProps = state => ({
    success: state.auth.success,
    error: state.auth.error,
    loading: state.auth.loading,
    resend: state.auth.resend,
    verify: state.auth.verify,

})
export default connect(mapStateToProps, {teacher_reset, teacher_verify})(TeacherForgottenPassword);
