import React, {useEffect, useState} from 'react'
import './css/AssignmentDetail.css';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { Button } from '@mui/material';

function AssignmentDetail() {
    const BASE_URL = 'http://127.0.0.1:8000'
    const [assignment, setAssignment] = useState([])
    const {course_id} = useParams()

    console.log("use params ", course_id)

    useEffect(() => {
        axios.get(BASE_URL + '/student-assignment-detail/' + course_id + '/')
        .then((response) => {
            setAssignment(response.data)
            console.log("Hi see me here ", response.data)
        })
        .catch((error) => {
            console.error(error)
        })
        // Get enrolled students
    },[])

console.log('Assignment ', assignment)
  return (
    <div className='assignment__detail'>
        <div className='title1'>
            <h2>{assignment.title}</h2>
        </div>
        <div className='bodyArticle' >
            <article>
              {assignment.detail}  
            </article>
            
        </div>
        <div className='btn_sub'>
        <Button>View Submisson </Button>
        </div>
    </div>
  )
}

export default AssignmentDetail