import React, { useEffect, useState } from 'react';
import './css/TeacherLogin.css';
import { Link, useNavigate } from 'react-router-dom';
import { connect } from 'react-redux';
import { teacher_login } from '../../Redux/Actions/auth';
import axios from 'axios';
import CSRFToken from '../../Components/CSRFToken';

const TeacherLogin1 = ({teacher_login, IsAuthenticated, loading, errorLogin, successsLogin}) => {
    const navigate = useNavigate()
    const [loginError, setLoginError] = useState('')

    const [teacherLoginData, setTeacheerLoginData] = useState({
        'email': '',
        'password':'',
    })

    const handleChange = (event) => {
        setTeacheerLoginData({
            ...teacherLoginData,
            [event.target.name]: event.target.value
        })
    }

    const {email, password} = teacherLoginData

    const handleSubmit = (event) => {
        event.preventDefault()
        if(password != '' && email != ''){
            setLoginError('')
            teacher_login(email, password)
        }
        else{
            setLoginError('Cannot submit empty field(s)')
        }
     }

     useEffect(() => {
        if(IsAuthenticated){
            navigate('/teacher-index')
        }
     },[IsAuthenticated])

    return(
    <div className='teacher__auth'>
        <div className="teacher__login">
            <div className='heading2'>
                <h2>Teachers Panel</h2>
            </div>
            
            <div className='login__card'>
                <div className="card__heading">
                    <h1 className='h1'>Teacher login</h1>
                    <form onSubmit={handleSubmit} className='form'>
                        <CSRFToken />
                        {
                            loginError ? <p className='errorLogin'>{loginError}</p> : ''
                        }
                        {
                            errorLogin ? <p className='errorLogin'>{errorLogin}</p> : ''
                        }
                        {
                            successsLogin ? <p className='errorLogin'>{successsLogin}</p> : ''
                        }
                        <div className='input_wrapper input'>
                               <label className='label2'>Email</label>
                        <input className='input' name='email' onChange={handleChange} value={email} type='email' placeholder='' autoFocus={true} />
                        </div>
                     
                        <div className='input_wrapper input'>
                               <label className='label2'>password</label>
                        <input className='input' name='password' onChange={handleChange} value={password} type='password' placeholder='' />
                        </div>
                        <button className='bttn' disabled={loading} type='submit'>{loading ? 'wait... ' : 'Submit' }</button>
                    </form>
                    <div className='register'>
                        <p>Don't have an account yet? <Link to='/teacher-register' >Register here</Link></p>
                        <p>Forgotten Password? <Link to="/reset-teacher-password">Click here</Link></p>
                    </div>
                </div>
            </div>
        </div>
    </div>
)      
}

const mapStateToProps = state => ({
    loading: state.auth.loading,
    IsAuthenticated: state.auth.IsAuthenticated,
    errorLogin: state.auth.errorLogin,
    successsLogin: state.auth.successsLogin,
})
export default connect(mapStateToProps, {teacher_login})(TeacherLogin1);
